function loadListeningPage(id,management=false,page=0,limit=20,force=false){
 if(!Number.isSafeInteger(page)||page<0||page*limit>10000000||![5,20].includes(limit))throw Error('常聽歌單頁碼不正確');
 const scope=listeningScope(id,management);if(!scope)return Promise.resolve();
 const view=listeningView;if(scope!==view.scope){view.scope=scope;view.cache.clear();}
 const key=listeningKey(id,management,page,limit),existing=view.cache.get(key);if(existing?.pending)return existing.pending;if(!force&&existing){renderListeningPanels();return Promise.resolve();}
 const entry={rows:[],total:0,loading:true,error:'',pending:null},visible=()=>limit===20?view.open&&!!$('#listening-panel')&&view.playerId===id&&view.management===management&&view.page===page:$('#listening-overview')?.dataset.player===id&&$('#listening-overview')?.dataset.management===String(management);
 const active=()=>scope===listeningScope(id,management)&&scope===view.scope&&view.cache.get(key)===entry;
 view.cache.set(key,entry);while(view.cache.size>4)view.cache.delete(view.cache.keys().next().value);renderListeningPanels();
 const pending=Promise.resolve().then(()=>{if(!active()||!visible())return null;if(demo||draft&&management){const rows=listenedSongs(state,id);return {rows:rows.slice(page*limit,(page+1)*limit),total:rows.length};}return api({op:'listeningHistoryPage',playerId:id,page,limit});}).then(result=>{
  if(!active())return;if(!result){view.cache.delete(key);return;}
  if(!Array.isArray(result.rows)||result.rows.length>limit||!Number.isSafeInteger(result.total)||result.total<result.rows.length)throw Error('常聽歌單資料不正確');
  const ids=new Set(),rows=result.rows.map(row=>{if(!row||typeof row.songId!=='string'||!row.songId||row.songId.length>128||ids.has(row.songId)||typeof row.title!=='string'||!row.title||row.title.length>1000||typeof row.artist!=='string'||row.artist.length>1000||!Number.isSafeInteger(row.listenedCount)||row.listenedCount<1||typeof row.requestable!=='boolean')throw Error('常聽歌曲資料不正確');ids.add(row.songId);return {songId:row.songId,title:row.title,artist:row.artist,listenedCount:row.listenedCount,requestable:row.requestable};});
  Object.assign(entry,{rows,total:result.total,loading:false,pending:null});renderListeningPanels();
 }).catch(error=>{if(!active())return;Object.assign(entry,{rows:[],total:0,loading:false,error:error.message||'讀取失敗',pending:null});renderListeningPanels();});entry.pending=pending;return pending;
}
