async function changePlayerArchived(id,archived){
 if(!isSuperAdmin()||!admin.accountId)throw Error('請先登入 PA Party總裁');if(localPlayerManagement())throw Error('封存管理請使用正式連線');
 if(typeof id!=='string'||!id||id.length>128||typeof archived!=='boolean')throw Error('玩家資料不正確');
 if(playerArchiveView.pending.size)return;
 const context=playerManagementContext(),identity=JSON.stringify([context.spaceId,context.roomId,context.actorKey]),revision=context.revision;
 const active=()=>isSuperAdmin()&&JSON.stringify([playerManagementContext().spaceId,playerManagementContext().roomId,playerManagementContext().actorKey])===identity;
 if(!confirm(archived?'封存此玩家？存歌、點歌與歷史都會保留；恢復前不能新增點歌。':'恢復此玩家的點歌使用權？既有存歌與歷史保持不變。'))return;
 if(!active())return;playerArchiveView.pending.add(id);
 try{
  const result=await api({op:'playerArchive',playerId:id,archived,revision,management:true});
  if(!active())return;
  if(!result||result.playerId!==id||result.archived!==archived||typeof result.changed!=='boolean'||!Number.isSafeInteger(result.revision)||result.revision<revision)throw Error('玩家封存結果不正確');
  if(state.revision>result.revision){toast('玩家資料已再次更新，請查看最新列表');return;}
  const target=state.players.find(p=>p.playerId===id);if(target)target.archived=archived;state.revision=result.revision;
  toast(archived?'玩家已封存，存歌與歷史保留':'玩家已恢復');
  if(playerArchiveView.open)await archivedPlayers.load({force:true});else render();
 }finally{playerArchiveView.pending.delete(id);if(playerArchiveView.open&&active()){const panel=$('#player-archive-panel');if(panel)panel.innerHTML=archivedPlayersPanel();}}
}

