function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function modal(title,body,submit){$('#dialog').innerHTML=`<div class="dialog-head"><h2>${h(title)}</h2>${button('✕','close','','','aria-label="關閉"')}</div><div class="dialog-body">${submit?'<form id="modal-form">':''}${body}<p class="error" id="dialog-error"></p>${submit?'<div class="actions dialog-actions"><button type="button" data-act="close">取消</button><button class="primary" type="submit">儲存</button></div></form>':''}</div>`;if(!$('#dialog').open)$('#dialog').showModal();if(submit)$('#modal-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,submitButton=form.querySelector('[type=submit]');submitButton.disabled=true;try{await submit(new FormData(form),form);$('#dialog').close();}catch(e){$('#dialog-error').textContent=e.message;if(e.liveSongId)$('#dialog-error').insertAdjacentHTML('beforeend','<div class="actions">'+button('前往現點','request',e.liveSongId,'primary','data-kind="live"')+'</div>');}finally{submitButton.disabled=false;}};}
const field=(name,label,value='',type='text',extra='')=>`<label>${h(label)}<input name="${name}" type="${type}" value="${h(value)}" ${extra}></label>`;
const area=(name,label,value='')=>`<label class="full">${h(label)}<textarea name="${name}">${h(value)}</textarea></label>`;
const nativeSelect=(name,label,values,value)=>`<label>${h(label)}<select name="${name}">${values.map(v=>{const [id,text]=Array.isArray(v)?v:[v,v];return `<option value="${h(id)}" ${String(value)===String(id)?'selected':''}>${h(text)}</option>`;}).join('')}</select></label>`;
const check=(name,label,on=false)=>`<label class="check-row"><input type="checkbox" name="${name}" ${on?'checked':''}>${h(label)}</label>`;
const formData=f=>Object.fromEntries(f.entries());
function paginate(items,key,size=10){const max=Math.max(1,Math.ceil(items.length/size));pages[key]=Math.min(Math.max(1,pages[key]||1),max);return {rows:items.slice((pages[key]-1)*size,pages[key]*size),nav:`<div class="pagination">${button('上一頁','page',key,'tiny',`data-step="-1" ${pages[key]===1?'disabled':''}`)}<label class="page-jump">第 <input type="number" min="1" max="${max}" value="${pages[key]}" data-page-key="${h(key)}" aria-label="輸入頁碼"> / ${max} 頁</label>${button('跳頁','jumpPage',key)}${button('下一頁','page',key,'tiny',`data-step="1" ${pages[key]===max?'disabled':''}`)}</div>`};}
function managerSessionExpired(response,data){return response.status===401||data?.code==='AUTH_EXPIRED'||['登入已到期，請重新登入','請重新登入管理','請使用總裁密碼重新登入','請先登入管理','請先登入'].includes(data?.error);}
function discardManagerSession(token){
 if(typeof token==='object'?(!token||admin!==token):(!token||admin?.token!==token))return false;
 const rooms=state.streamers,currentRoom=state.currentStreamer;
 admin=null;draft=null;full=null;signatures={};selectedPlayer=null;state=empty();state.streamers=rooms;state.currentStreamer=currentRoom;
 put('admin',null);put('draft',null);
 // Drafts contain management data and must not reappear under a later manager identity.
 for(const key of Object.keys(localStorage))if(key.startsWith('papa-v2-'+(demo?'preview-':'')+'draft-'))localStorage.removeItem(key);
 if(route==='admin'){route='home';location.hash='home';}
 document.querySelectorAll('dialog[open]').forEach(dialog=>dialog.close());header();$('#app').innerHTML=card('請重新登入管理','<p>管理登入已失效，請重新輸入密碼。</p>'+button('管理入口','admin'),true);
 return true;
}
async function deviceTransport(body){
 const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json',apikey:PUBLISHABLE_KEY},body:JSON.stringify({streamer:streamerSlug,...body})}),data=await r.json();
 if(!r.ok||data.error)throw Object.assign(new Error(data.error||'連線失敗'),{authExpired:r.status===401||data.code==='AUTH_EXPIRED'||/(?:裝置)?登入已到期|MEMBERSHIP_|ACCOUNT_DISABLED|SESSION_ACCOUNT_MISMATCH/.test(data.error||'')});
 return data;
}
if(!demo)deviceLogin=createWebDeviceLogin({transport:deviceTransport,appVersion:'space-foundation-1008'});
function saveEntryIdentity(identity){
 if(identity?.role==='player'){session=identity;put('player',session);}
 else {admin=identity;put('admin',admin);}
}
function showSpaceEntry(result=null){
 if(!state.currentStreamer)state=publicView(upgradePlatform(empty()),null,clock(),'papa');
 header();entryChoices=result?.spaces||[];
 const choices=entryChoices.map(space=>button(h(space.name),'enterSpace',space.id,'tiny')).join('');
 $('#app').innerHTML=card('PA Party',!entryIdentity
  ?'<p>登入後進入你已加入的空間。</p><div class="actions">'+button('登入','login','','primary')+button('管理登入','admin')+'</div>'
  :choices?'<p>選擇你的空間。</p><div class="actions">'+choices+'</div>'+((entryOffset||result.hasMore)?'<div class="pagination">'+button('上一頁','entryPage','-1','tiny',entryOffset?'':'disabled')+button('下一頁','entryPage','1','tiny',result.hasMore?'':'disabled')+'</div>':'')
  :'<p>目前沒有可進入的空間。請聯絡管理者確認使用權限。</p><div class="actions">'+button('登出',entryIdentity.role==='player'?'logout':'adminLogout')+'</div>',true);
}
async function enterSpace(space){
 if(!entryIdentity)throw Error('請先登入');
 let next;
 if(entryIdentity.device)next=await entryController.enter(space);
 else {if(space.id!=='space-001')throw Error('此瀏覽器尚不支援跨空間登入，請使用支援安全裝置登入的瀏覽器');next={identity:entryIdentity,url:spaceDestination(location.href,spaceMount,space,{page:route==='admin'?'admin':'home'})};}
 saveEntryIdentity(next.identity);draft=null;signatures={};roomSearch.generation++;clearTimeout(roomSearch.timer);
 if(new URL(next.url).href!==location.href){location.replace(next.url);return false;}
 entryPending=false;return true;
}
async function openSpaceEntry({list=false,offset=0}={}){
 entryPending=true;entryOffset=offset;entryIdentity=route==='admin'?admin:session||admin;
 if(!entryIdentity){showSpaceEntry();return false;}
 let result;
 if(entryIdentity.device){
  if(!deviceLogin)throw Error('請使用原本登入裝置');
  entryController=createWebSpaceEntry({deviceLogin,transport:deviceTransport,identity:entryIdentity,url:location.href,mountUrl:spaceMount});
  result=await entryController.resolve({list,offset});entryIdentity={...entryIdentity,...result.identity};saveEntryIdentity(entryIdentity);
 }else {
  const slug=list?null:requestedSpace(location.href,spaceMount),response=await deviceTransport({op:'spaceEntry',token:entryIdentity.token,slug,streamer:entryIdentity.streamerSlug||streamerSlug,limit:50,offset});
  result={...response,...chooseSpaceEntry(response,list?{}:entryIdentity,slug)};
 }
 entryMembershipCount=result.membershipCount||0;
 if(result.kind==='destination')return enterSpace(result.space);
 showSpaceEntry(result);return false;
}
async function api(body){
 const identity=(isAdmin()||body.management)?admin:session;
 if(identity?.device){
  if(!deviceLogin)throw Error('此瀏覽器無法恢復裝置登入，請使用原本登入裝置');
  try{const token=await deviceLogin.access(identity);if(!token)throw Object.assign(Error('登入已到期，請重新登入'),{authExpired:true});
   if(((isAdmin()||body.management)?admin:session)!==identity)throw Error('登入身分已變更，請重新操作');identity.token=token;
  }catch(error){if(error.authExpired){if(identity===admin)discardManagerSession(identity);else if(identity===session){session=null;put('player',null);}}throw error;}
 }
 if(admin&&(isAdmin()||body.management)&&!admin.legacy&&admin.accessUntil<Date.now()&&body.op!=='refreshAdmin'){
  const previousToken=admin.token,r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json',apikey:PUBLISHABLE_KEY},body:JSON.stringify({op:'refreshAdmin',refreshToken:admin.refreshToken})}),v=await r.json();
  if(!r.ok||v.error){if(managerSessionExpired(r,v))discardManagerSession(previousToken);throw new Error(v.error||'請重新登入管理');}
  if(admin?.token!==previousToken)throw new Error('登入身分已變更，請重新操作');
  admin={...admin,...v,accessUntil:Date.now()+(v.expiresIn-60)*1000};put('admin',admin);
 }
 const managerToken=(isAdmin()||body.management)?admin?.token:null,payload={streamer:streamerSlug,token:(isAdmin()||body.management)?admin?.token:session?.token,signatures,...body};
 const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json',apikey:PUBLISHABLE_KEY},body:JSON.stringify(payload)}),data=await r.json();
 if(!r.ok||data.error){if(managerSessionExpired(r,data)&&identity?.device){await deviceLogin.logout(identity).catch(()=>{});if(identity===session){session=null;put('player',null);}}if(managerToken&&payload.token===managerToken&&managerSessionExpired(r,data))discardManagerSession(managerToken);throw new Error(data.error||'連線失敗');}
 if(managerToken&&admin?.token!==managerToken)throw new Error('登入身分已變更，請重新操作');
 if(data.signatures)signatures=data.signatures;if(data.now)offset=timeValue(data.now)-Date.now();return data;
}
async function refresh(force=false){
 if(busy||entryPending)return;
 if(refreshInFlight){await refreshInFlight;if(force)return refresh(true);return;}
 const run=(async()=>{
  if(demo||draft&&isAdmin()){full=(draft&&isAdmin()?draft.state:null)||get('demo')||full;state=publicView(full,actor(),clock(),streamerSlug);render();return;}
  const fullRead=force||Date.now()-lastFullRefreshAt>=300000;
  const r=await api({op:'read',revision:fullRead?-1:state.revision,...((isAdmin()?selectedPlayer:session?.playerId)?{profilePlayerId:isAdmin()?selectedPlayer:session.playerId}:{})});
  if(entryPending)return;
  if(r.state){state={...state,...r.state};if(fullRead)lastFullRefreshAt=Date.now();render();}
  if(!r.ready&&!isAdmin())$('#app').innerHTML=`<section class="card"><h2>歌本整理中 ♡</h2><p>管理員完成資料移轉後就能開始點歌。</p>${button('管理入口','admin')}</section>`;
 })();
 refreshInFlight=run;try{return await run;}finally{if(refreshInFlight===run)refreshInFlight=null;}
}
async function dispatch(type,data){if(busy)throw new Error('上一筆還在處理');busy=true;try{if(demo||draft&&isAdmin()){const before=structuredClone(full);if(draft&&isAdmin()){if(!draft.journal)throw Error('舊草稿請先下載備份，再重新建立');const recorded=recordRoomDraftAction(full,draft.journal,{type,data},actor(),clock());full=recorded.state;draft.journal=recorded.journal;}else full=mutate(full,{type,data,streamer:streamerSlug},actor(),clock());notifications.localChange(before,full,{type,data,streamer:streamerSlug},actor());if(draft&&isAdmin()){draft.state=full;put('draft',draft);}else put('demo',full);state=publicView(full,actor(),clock(),streamerSlug);}else{const r=await api({op:'mutate',revision:state.revision,action:{type,data}});state={...state,...r.state};}if(['song','songsBulk'].includes(type))invalidateCatalogTabs();render();notifications.refresh().catch(()=>{});}finally{busy=false;}}
function switchStreamer(slug){if(slug===streamerSlug)return;location.href=streamerDestination(location.href,slug,{role:admin?.role,managedSlug:admin?.streamerSlug,subtab,adminTab:tab});}
document.addEventListener('change',e=>{if(e.target.id==='header-streamer')switchStreamer(e.target.value);if(e.target.id==='fate-category'){fateCategory=e.target.value;fateSeen=[];fateId=null;$('#fate-result').innerHTML=fateResultHtml();}});
async function go(next){if(entryPending){if(next==='admin'&&!admin){await adminLogin();return;}await openSpaceEntry();return;}if(next==='admin'&&admin?.role==='streamer_admin'&&admin.streamerSlug!==streamerSlug){const u=new URL(location.href);u.hash='admin';location.href=streamerDestination(u.href,admin.streamerSlug,{role:admin.role,managedSlug:admin.streamerSlug});return;}signatures={};route=next;location.hash=next;filters={q:'',tags:[],language:''};pages={};roomSearch.generation++;clearTimeout(roomSearch.timer);if(next==='admin'&&!admin){route='home';await adminLogin();return;}if(next==='center'&&!session){route='home';await loginDialog();return;}await refresh(true);if(next==='common-book')await loadCommonBook(0);if(pendingCommonRequest&&session){const item=pendingCommonRequest;pendingCommonRequest=null;await requestSong(item.songId,item.kind);}}
const notifications=createNotifications({api:b=>api({...b,management:!!admin,streamer:admin?.role==='streamer_admin'?admin.streamerSlug:streamerSlug}),apiUrl:API,apiKey:PUBLISHABLE_KEY,context:()=>({spaceId:admin?.spaceId||session?.spaceId||state.currentStreamer?.spaceId||'space-001',deviceSessionId:(admin||session)?.sessionId,demo:demo||entryPending||!!(draft&&isAdmin()),role:admin?(admin.role||'super_admin'):'player',recipient:admin?(isSuperAdmin()?'__super__':'__admin__'):session?.playerId,streamer:admin?(isSuperAdmin()?'__global__':admin.streamerSlug):streamerSlug,streamerName:admin&&isSuperAdmin()?'全部主播':state.currentStreamer?.display_name}),toast,onUpdate:()=>{chat.refresh().catch(()=>{});if(!busy&&!$('#dialog').open&&!document.activeElement?.matches('input,textarea,select'))refresh().catch(()=>{});}});
const chat=createChat({api,context:()=>({spaceId:(isAdmin()?admin?.spaceId:session?.spaceId)||state.currentStreamer?.spaceId||'space-001',manager:isAdmin(),role:isAdmin()?admin?.role:'player',playerId:session?.playerId,streamer:streamerSlug,streamerName:hostName(),demo:demo||entryPending||!!draft}),toast,onRead:()=>notifications.refresh().catch(()=>{}),realtimeAvailable:()=>notifications.realtimeAvailable()});
document.addEventListener('click',e=>{if(e.target.closest('[data-open-chat]'))chat.open().catch(e=>toast(e.message));});
const board=createBoard({api,context:()=>({spaceId:(isAdmin()?admin?.spaceId:session?.spaceId)||state.currentStreamer?.spaceId||'space-001',manager:isAdmin(),role:isAdmin()?admin?.role:'player',playerId:session?.playerId,streamer:streamerSlug,streamerName:hostName(),demo:demo||entryPending||!!draft}),toast});
document.addEventListener('click',e=>{if(e.target.closest('[data-open-board]'))board.open().catch(e=>toast(e.message));});
function header(){const p=me();$('#header').innerHTML=`${demo?'<div class="offline">預覽測試模式 · 資料只在這台裝置，未連正式資料庫</div>':''}<div class="header-inner">${button('<span class="brand-logo" role="img" aria-label="PA • PARTY"></span>','home','','brand')}<div class="login-status">${p?`<b title="${h(p.name)}">👤 ${h(p.name)}${session.loginId?'｜ID '+h(session.loginId):''}</b><small>可以開始點歌嚕 ♡</small>`:''}</div><div class="header-actions"><label class="header-streamer"><span>主播</span><select id="header-streamer" aria-label="切換主播">${state.streamers?.filter(r=>r.active||isAdmin()&&isSuperAdmin()).map(r=>`<option value="${h(r.slug)}" ${r.slug===streamerSlug?'selected':''}>${h(r.display_name)}</option>`).join('')||''}</select></label>${button(h('回'+hostName()+'首頁'),'home')}${button('歌本','book')}${button('共同歌本','common-book')}${p?button('玩家中心','center')+button('登出','logout'):button('登入','login')}${entryMembershipCount>1?button('切換空間','switchSpace'):''}${button('管理','admin')}${chat.button()}${board.button()}${notifications.button()}</div></div>`;}
function card(title,body,wide=false,action=''){return `<section class="card ${wide?'wide':''}">${title||action?`<div class="section-head"><h2>${title}</h2>${action}</div>`:''}${body}</section>`;}
function songRows(rows){return rows.map((s,i)=>{const c=crownFor(state,s.songId,clock());return `<div class="song"><span class="number">${i+1}</span><div class="info"><b>${h(s.title)}${c?' 👑':''}</b><small>${h(s.artist)} · ${plays(s)} 次</small>${s.murmur?`<div class="subtle">💬 ${h(hostName())}碎碎念：${h(s.murmur)}</div>`:''}<div>${(s.tags||[]).map(t=>`<span class="tag">${h(t)}</span>`).join('')}</div></div><div class="actions">${button('提歌','request',s.songId,'tiny','data-kind="saved"')}${button('現點','request',s.songId,'tiny','data-kind="live"')}${favoriteButton(s.songId)}</div></div>`;}).join('')||blank(say('empty'));}
function hour(){const current=state.hourBucket===hourKey(clock()),grant=(me()?.quotaRights||[]).find(x=>x.streamer_id===state.currentStreamer?.id),quota=isAdmin()?savedQuota(state,clock()):current?(state.hourlyPersonal||{used:state.hourlyUsed||0,reserved:state.hourlyReserved||0,extraQuota:0,personalUsed:0,extraRemaining:0,commonRemaining:Math.max(0,state.settings.hourlyLimit-(state.hourlyUsed||0)-(state.hourlyReserved||0))}):{used:0,reserved:0,extraQuota:grant?.extra_quota||0,personalUsed:0,extraRemaining:grant?.extra_quota||0,commonRemaining:Number(state.settings.hourlyLimit)},available=quota.commonRemaining+quota.extraRemaining,limit=Number(state.settings.hourlyLimit)+quota.extraQuota,occupied=quota.used+quota.reserved+quota.personalUsed,remaining=Math.ceil((3600000-(Date.now()+offset)%3600000)/60000);return '<small>🕒 本小時提歌額度</small><strong>'+occupied+' / '+limit+(!available?' <span class="quota-full">提滿了</span>':'')+'</strong><small>還可使用 '+available+' 首額度'+(quota.extraQuota?'（共用 '+quota.commonRemaining+' ＋ 專屬 '+quota.extraRemaining+'）':'；待唱保留 '+quota.reserved+' 首')+'</small><small>距離下一次提歌重置還有 '+remaining+' 分鐘</small>';}
function statsHtml(s){return `<div class="stats"><div class="stat">🎵 收到<b>${s.received}</b></div><div class="stat">🎤 唱了<b>${s.sung}</b></div><div class="stat">💾 存了<b>${s.saved}</b></div></div>`;}
function crownsHtml(rows,adminMode=false){return `<div class="crown-grid">${rows.map(c=>{const remaining=c.expiresAt?(timeValue(c.expiresAt)-Date.now()-offset)/86400000:Infinity,status=!c.activatedAt?'⏳ 待確認':!isActive(c,clock())?'🕒 已過期':remaining<=7?'⚠️ 即將到期':!c.expiresAt?'♾️ 永久':'👑 生效中';return `<div class="crown"><h3>${h(song(c.songId)?.title||c.title||'歌曲待核對')} 👑</h3><p>${h(c.tier)} · ${h(c.ownerName||playerName(c.playerId))}</p>${adminMode||c.activatedAt?`<p>${h(status)}${c.expiresAt?' · '+time(c.expiresAt):''}</p>`:''}<p>其他玩家現點 ${money(c.price)}／首＋雙費 ${money(state.settings.liveDouble??500)}</p>${adminMode?button('編輯／生效','editCrown',c.id)+button('時間','recordTime',c.id,'tiny','data-table="crowns"'):button('👑 點冠歌','requestCrown',c.id,'tiny primary')}</div>`;}).join('')||blank('還沒有冠歌，王冠等你戴 ♡')}</div>`;}
function currentCards(){return state.cards.filter(c=>timeValue(c.startsAt)<=Date.now()+offset&&(!c.expiresAt||timeValue(c.expiresAt)>Date.now()+offset));}
function photoHtml(c){return `<div class="photo"><img src="${h(c.thumbnail||c.url)}" alt="${h(c.description||'照片卡片')}" loading="lazy"><p>${h(c.description)}</p><small>${time(c.startsAt)} ～ ${c.expiresAt?time(c.expiresAt):'永久'}</small></div>`;}
function photoCarousel(){const rows=currentCards();if(!rows.length)return blank('照片還在路上，先想像一下 ♡');photoIndex=(photoIndex+rows.length)%rows.length;return photoHtml(rows[photoIndex])+`<div class="photo-controls">${button('←','photoPrev')}<small>${photoIndex+1} / ${rows.length}</small>${button('→','photoNext')}</div>`;}
function fateResultHtml(){const chosen=state.songs.find(s=>s.songId===fateId);if(!chosen||fateCategory.startsWith('tag:')&&!(chosen.tags||[]).includes(fateCategory.slice(4)))return '<small>讓命運幫你選一首 ♡</small>';return `<small>✨ 命運選中了</small><b>${h(chosen.title)}${crownFor(state,fateId,clock())?' 👑':''}</b><small>${h(chosen.artist)}</small>${chosen.murmur?`<p>💬 ${h(chosen.murmur)}</p>`:''}<div class="actions" style="justify-content:center">${button('🎤 提歌','request',fateId,'tiny','data-kind="saved"')}${button('🎁 現點','request',fateId,'tiny','data-kind="live"')}${button('🎲 這命我不要','fate')}</div>`;}
