function newPracticePanelHtml(){const view=newPracticeView;return (view.management?'<p class="muted">拖曳調整順序，手機也可按上移／下移。只改本主播排序。</p>':'')+(view.loading?blank('讀取新練歌曲中…'):view.error?'<p class="error">'+h(view.error)+'</p>'+button('重新讀取','newPracticeRetry'):view.management?view.rows.map(s=>'<article class="song new-practice-row" draggable="true" data-practice-song="'+h(s.songId)+'"><div class="info"><b>'+h(s.title)+(s.hidden?' <span class="tag">已隱藏</span>':'')+'</b><small>'+h(s.artist)+'</small></div><div class="actions">'+button('上移','newPracticeMove',s.songId,'tiny','data-target="'+h(s.previousSongId||'')+'" data-position="before" '+(s.previousSongId?'':'disabled'))+button('下移','newPracticeMove',s.songId,'tiny','data-target="'+h(s.nextSongId||'')+'" data-position="after" '+(s.nextSongId?'':'disabled'))+'</div></article>').join('')||blank('目前沒有新練歌曲'):songRows(view.rows))+'<div class="pagination">'+button('上一頁','newPracticePage','-1','tiny',view.page&&!view.loading?'':'disabled')+'<small>第 '+(view.page+1)+' 頁 · 共 '+view.total+' 首</small>'+button('下一頁','newPracticePage','1','tiny',(view.page+1)*20<view.total&&!view.loading?'':'disabled')+'</div>';}
function renderNewPractice(){const panel=$('#new-practice-panel');if(newPracticeView.open&&panel)panel.innerHTML=newPracticePanelHtml();}
async function openNewPractice(management=false){if(management&&!isAdmin())throw Error('請先登入管理');const view=newPracticeView;view.generation++;view.open=true;view.management=management;view.pending=null;view.loading=false;modal(management?'新練歌曲排序':'✨ 新練歌曲','<div id="new-practice-panel"></div>');const dialog=$('#dialog'),panel=$('#new-practice-panel');dialog.addEventListener('close',()=>{view.open=false;view.generation++;view.pending=null;},{once:true});if(management){let dragged=null;panel.addEventListener('dragstart',e=>{const row=e.target.closest('[data-practice-song]');if(!row)return;dragged={id:row.dataset.practiceSong,scope:newPracticeScope()};e.dataTransfer.setData('text/plain',dragged.id);e.dataTransfer.effectAllowed='move';});panel.addEventListener('dragover',e=>{if(dragged&&e.target.closest('[data-practice-song]')){e.preventDefault();e.dataTransfer.dropEffect='move';}});panel.addEventListener('dragend',()=>{dragged=null;});panel.addEventListener('drop',e=>{const row=e.target.closest('[data-practice-song]'),source=dragged;dragged=null;if(!row||!source||source.scope!==newPracticeScope())return;e.preventDefault();if(source.id!==row.dataset.practiceSong){const r=row.getBoundingClientRect(),position=e.clientY<r.top+r.height/2?'before':'after';moveNewPractice(source.id,row.dataset.practiceSong,position).catch(error=>toast(error.message));}});}await loadNewPractice(0);}
function loadNewPractice(page=0,force=false){const view=newPracticeView;if(!view.open||!$('#new-practice-panel'))return Promise.resolve();if(!Number.isSafeInteger(page)||page<0||page*20>10000000)throw Error('新練歌曲頁碼不正確');const scope=newPracticeScope();if(scope!==view.scope){view.scope=scope;view.cache.clear();view.pending=null;view.generation++;}const key=scope+':'+page;view.page=page;if(!force&&view.pending?.key===key)return view.pending.promise;if(!force&&view.cache.has(key)){Object.assign(view,view.cache.get(key),{loading:false,error:''});renderNewPractice();return Promise.resolve();}const generation=++view.generation,active=()=>view.open&&!!$('#new-practice-panel')&&generation===view.generation&&scope===newPracticeScope();view.loading=true;view.error='';renderNewPractice();const promise=Promise.resolve().then(()=>{if(!active())return null;if(demo||draft&&isAdmin()){const rows=newPracticeSongs(state.songs).filter(s=>view.management||!s.hidden);return {rows:rows.slice(page*20,(page+1)*20).map((s,i)=>({...s,previousSongId:rows[page*20+i-1]?.songId||null,nextSongId:rows[page*20+i+1]?.songId||null})),total:rows.length};}return api({op:'newPracticePage',management:view.management,page,limit:20});}).then(result=>{if(!active())return;if(!Array.isArray(result?.rows)||result.rows.length>20||!Number.isSafeInteger(result.total)||result.total<result.rows.length||result.rows.some(s=>!s||typeof s.songId!=='string'||s.streamer_id&&s.streamer_id!==state.currentStreamer?.id||typeof s.title!=='string'||typeof s.artist!=='string'))throw Error('新練歌曲資料不正確');const rows=result.rows.map(s=>({...s,plays:song(s.songId)?.plays??s.plays??0}));Object.assign(view,{rows,total:result.total,loading:false,pending:null});view.cache.set(key,{rows,total:result.total});if(view.cache.size>4)view.cache.delete(view.cache.keys().next().value);renderNewPractice();}).catch(error=>{if(!active())return;Object.assign(view,{loading:false,pending:null,error:error.message||'讀取失敗'});renderNewPractice();});view.pending={key,promise};return promise;}
async function moveNewPractice(songId,targetId,position){if(!newPracticeView.open||!newPracticeView.management||!isAdmin())throw Error('請先登入管理');if(!targetId||songId===targetId)return;await dispatch('newPracticeOrder',{songId,targetId,position});newPracticeView.cache.clear();await loadNewPractice(newPracticeView.page,true);}
