 const banner='<section class="hero integrated-hero">'+(heroImage?'<img src="'+h(heroImage)+'" alt="'+h(state.currentStreamer?.home_title||'音樂時光')+'">':'<div class="hero-placeholder" aria-hidden="true"></div>')+'<div class="hero-overlay">'+home.fieldOrder.filter(k=>home.fields[k]).map(k=>heroFields[k]).join('')+'</div></section>';
 const search=card('找找'+h(hostName())+'會唱的歌👀','<input id="home-search" aria-label="搜尋歌曲" placeholder="歌名、歌手、語言、標籤都可以…"><div id="home-results">'+blank('給我一點線索，幫你翻歌本 ♡')+'</div>',true,button('完整歌本 ↗','book'));
 const fresh=card('✨ 新練歌曲',songRows(newPracticeSongs(state.songs).filter(s=>!s.hidden).slice(0,5)),true,button('查看更多','newPractice'));
 const fate=card('🎲 今天聽什麼？','<div class="fate-toolbar"><select id="fate-category" aria-label="命運分類">'+[['all','完全交給命運'],...fateCategories(state.settings,state.songs).map(t=>['tag:'+t,t])].map(([v,label])=>'<option value="'+h(v)+'" '+(v===fateCategory?'selected':'')+'>'+h(label)+'</option>').join('')+'</select>'+button('🎲 抽一首','fate','','tiny')+'</div><div id="fate-result" class="fate">'+fateResultHtml()+'</div>');
 const credits=card('💾 我的存歌',p?'<div class="stat">'+h(p.name)+' 在本主播的存歌<b>'+storedBalanceHtml(p.playerId)+'</b></div><p class="muted">所有綁定 ID 共用；完成演唱才扣。</p>'+'<small>'+venueName(venuePolicySettings(state.settings).current_space)+'待唱保留 '+reservedCredits(state,p.playerId)+' 首'+(venuePolicySettings(state.settings).current_space==='radio'?'；電台不足時整首使用聲瑪存歌。':'')+'</small>'+button('查看完整記錄','myLedger','','primary'):blank('登入後，幫你打開存歌袋 ♡')+button('玩家登入','login'));
 const ranking=card('🏆 '+(venuePolicySettings(state.settings).radio_enabled?venueName(venuePolicySettings(state.settings).current_space):'')+'存歌排行榜','<small>匿名 Top 5</small>'+ (rank.filter(x=>x.rank<=5).map(x=>'<div class="song"><div class="info">第 '+x.rank+' 名</div><b>'+x.amount+' 首</b></div>').join('')||blank())+'<div class="notice">'+(p?mine?'你的排名：第 '+mine.rank+' 名　存歌：'+mine.amount+' 首':'測試玩家不列入排行':'請登入查看自己的名次')+'</div>');
