 if(state.settings.home){const modules={hero:banner,search,fresh,fate,credits,popular:card('🔥 熱門點歌',songRows(popular)),recommendations,crowns:card('👑 冠歌',crownsHtml(state.crowns.filter(c=>isActive(c,clock())||c.legacyDisplay)),true,button('如何冠歌？','crownHelp')),ranking,cards,wishes:card('🌟 許願池','<p>希望'+h(hostName())+'可以學會這首</p>'+button('投一個願望','wish','','primary')),recap:card('🌙 本晚回顧','<small>'+dayLabel(clock())+' · 每天 19:00 換場</small>'+statsHtml(summary)),manual:card('📖 說明書','<div class="manual">'+h(hostText(state.settings.manual).replace('提歌扣存歌','完成演唱才扣存歌'))+'</div>',false,button('價格表','prices'))};$('#app').innerHTML='<div class="grid custom-home">'+home.order.filter(k=>home.visible[k]).map(k=>'<div class="home-module home-module-'+k+(['hero','search','fresh','crowns'].includes(k)?' wide':'')+'" data-home-module="'+k+'">'+modules[k]+'</div>').join('')+'</div>';return;}
 $('#app').innerHTML=banner+'<div class="grid">'+search+fresh+'<div class="compact-pair mini-pair">'+fate+credits+'</div>'+card('🔥 熱門點歌',songRows(popular))+recommendations+card('👑 冠歌',crownsHtml(state.crowns.filter(c=>isActive(c,clock())||c.legacyDisplay)),true,button('如何冠歌？','crownHelp'))+'<div class="home-stack">'+ranking+cards+'</div><div class="compact-pair">'+card('🌟 許願池','<p class="muted">希望'+h(hostName())+'可以學會這首<br>需要使用玩家身分投遞</p>'+button('投一個願望','wish','','primary'))+card('🌙 本晚回顧','<small>'+dayLabel(clock())+' · 每天 19:00 換場</small>'+statsHtml(state.summary||stats(state,clock())))+'</div>'+card('📖 說明書','<div class="manual">'+h(hostText(state.settings.manual).replace('提歌扣存歌','完成演唱才扣存歌'))+'</div>',false,button('價格表','prices'))+'</div>';
