function recommendSongs(s,id){const history=s.queue.flatMap(q=>q.items?q.items.map(i=>({...q,songId:i.songId})):q).filter(q=>q.playerId===id&&q.status==='completed'&&!q.selfProvided&&!q.test),artists=new Set(),tags=new Set();for(const q of history){const item=s.songs.find(x=>x.songId===q.songId);if(item){item.artist.split(/[／/,，]/).forEach(x=>artists.add(x.trim()));item.tags.forEach(x=>tags.add(x));}}const seed=id||'guest',hash=str=>{let n=2166136261;for(const char of str)n=Math.imul(n^char.charCodeAt(0),16777619);return n>>>0;};return [...s.songs].sort((a,b)=>{const score=x=>x.artist.split(/[／/,，]/).filter(y=>artists.has(y.trim())).length*3+x.tags.filter(y=>tags.has(y)).length*2;return score(b)-score(a)||hash(seed+liveDay(clock())+a.songId)-hash(seed+liveDay(clock())+b.songId);}).slice(0,5);}

function filteredSongs(){return state.songs.filter(s=>(!filters.language||s.cat===filters.language)&&matchesSong(s,filters.q,filters.tags)&&(!isAdmin()||(songCatalogStatusFilter==='all'||(s.catalogStatus||'unlinked')===songCatalogStatusFilter)&&(songVisibilityFilter==='all'||(songVisibilityFilter==='hidden')===!!s.hidden)));}
function roomSearchKey(q,tags,page,view='book'){return JSON.stringify([state.currentStreamer?.spaceId||'space-001',state.currentStreamer?.id||streamerSlug,view==='songs'?[!!admin,admin?.role||null,admin?.accountId||null,admin?.streamer_id||null]:[!!session,session?.role||null,session?.accountId||null,session?.playerId||null],streamerSlug,state.revision,view,String(q).trim(),[...tags].sort(),page,view==='home'?'':filters.language||'',view==='songs'?songVisibilityFilter:'visible',view==='songs'?songCatalogStatusFilter:'all']);}
function bookSearchResult(){
 if(!filters.q.trim()&&!isAdmin()||demo||draft)return null;
 const view=isAdmin()?'songs':'book',current=roomSearch[view];
 const page=current?.key===roomSearchKey(filters.q,filters.tags,current?.page||0,view)?current.page:0;
 const result=current,key=roomSearchKey(filters.q,filters.tags,page,view);
 if(!result||result.key!==key){scheduleMissingRoomSearch(view,key);return {rows:[],nav:'',loading:true};}
 if(result.localFallback){const local=paginate(filteredSongs(),view,20);return {...local,loading:false,nav:'<p class="muted">歌詞搜尋暫時無法連線，以下僅搜尋歌名、歌手與標籤。</p>'+local.nav};}
 const rows=result.songIds.map(id=>song(id)).filter(Boolean);
 return {rows,loading:false,nav:`<div class="pagination">${button('上一頁','roomSearchPage','-1','tiny',page?'':'disabled')}<small>第 ${page+1} 頁${result.total?' · 共 '+result.total+' 首':''}</small>${button('下一頁','roomSearchPage','1','tiny',result.hasMore?'':'disabled')}</div>`};
}
function scheduleMissingRoomSearch(view,key){
 if(roomSearch.pendingKey===key||roomSearch.scheduledKey===key)return;
 roomSearch.scheduledKey=key;setTimeout(()=>{if(roomSearch.scheduledKey!==key)return;roomSearch.scheduledKey=null;const currentView=isAdmin()?'songs':'book';if((view==='songs'?route==='admin'&&tab==='songs':route==='book')&&currentView===view&&roomSearchKey(filters.q,filters.tags,0,view)===key)loadRoomSongSearch(view,filters.q,filters.tags,0);},350);
}
async function loadRoomSongSearch(view,q,tags=[],page=0){
 const text=String(q||'').trim();if(!text&&view!=='songs'||demo||draft)return;
 page=Math.max(0,page);const key=roomSearchKey(text,tags,page,view);if(roomSearch.pendingKey===key)return;const generation=++roomSearch.generation,cached=roomSearch.cache.get(key);roomSearch.pendingKey=key;
 let response;
 if(cached&&Date.now()-cached.at<30000)response=cached.data;
 else if(roomSearch.unsupported)response={localFallback:true};
 else try{response=await api({op:'songSearchRoom',q:text,tags,limit:view==='home'?5:20,offset:page*(view==='home'?5:20),...(view!=='home'&&filters.language?{language:filters.language}:{}),...(view==='songs'?{visibility:songVisibilityFilter,catalogStatus:songCatalogStatusFilter}:{})});
  if(roomSearch.cache.size>50)roomSearch.cache.clear();roomSearch.cache.set(key,{at:Date.now(),data:response});
 }catch(err){response={localFallback:true};if(/未知操作|不支援|unsupported|unknown op/i.test(err.message))roomSearch.unsupported=true;}
 if(roomSearch.pendingKey===key)roomSearch.pendingKey=null;
 if(key!==roomSearchKey(text,tags,page,view)||generation!==roomSearch.generation||view!=='home'&&((view==='songs'?(route!=='admin'||tab!=='songs'):route!=='book')||filters.q.trim()!==text)||view==='home'&&(route!=='home'||$('#home-search')?.value.trim()!==text))return;
 const result={key,page,songIds:response.songIds||[],total:response.total||0,hasMore:!!response.hasMore,localFallback:!!response.localFallback};roomSearch[view]=result;
 if(view==='home'){const holder=$('#home-results');if(holder)holder.innerHTML=songRows(result.localFallback?state.songs.filter(s=>matchesSong(s,text)).slice(0,5):result.songIds.map(id=>song(id)).filter(Boolean));}
 else renderSongResults();
}
function visibleLanguages(){
 if(roomLanguages.data?.mode==='custom')return roomLanguages.data.languages||[];
 const used=[...new Set(state.songs.map(row=>String(row.cat||'')).filter(Boolean))],listed=roomLanguages.data?.languages||[];
 return used.map(name=>listed.find(row=>row.name===name)||{name,sortOrder:9999}).sort((a,b)=>(a.sortOrder??9999)-(b.sortOrder??9999)||a.name.localeCompare(b.name,'zh-TW'));
}
function languageOptionsHtml(){return '<option value="">全部語言</option>'+visibleLanguages().map(row=>'<option value="'+h(row.name)+'" '+(filters.language===row.name?'selected':'')+'>'+h(row.name)+'</option>').join('');}
function scheduleRoomLanguages(){
 if(demo||draft||roomLanguages.loading||Date.now()-roomLanguages.loadedAt<300000)return;
 roomLanguages.loading=true;setTimeout(async()=>{
  try{roomLanguages.data=await api({op:'catalogLanguageFilter'});}catch{ /* Metadata-only local filters keep older deployments usable. */ }
  finally{roomLanguages.loadedAt=Date.now();roomLanguages.loading=false;const select=$('#song-language');if(select){if(filters.language&&!visibleLanguages().some(row=>row.name===filters.language)){filters.language='';roomSearch.generation++;renderSongResults();}select.innerHTML=languageOptionsHtml();}}
 },0);
}
async function editLanguageFilters(){
 if(!isAdmin())return;
 if(demo||draft)return toast('語言篩選設定請在正式主播後台使用');
 const [settings,templates]=await Promise.all([api({op:'catalogLanguageFilter',management:true}),api({op:'catalogTemplates',management:true})]);
 const selected=new Set(settings.languageIds||[]),choices=(templates.languages||[]).filter(row=>row.active!==false||selected.has(row.id));
 modal('本主播歌本的語言篩選',nativeSelect('mode','顯示方式',[['auto','只顯示本主播已有的語言'],['custom','自行選擇要顯示的語言']],settings.mode||'auto')+'<p class="muted">只調整歌本篩選選項，不會刪除歌曲或修改歌曲語言。</p><div class="chips">'+choices.map(row=>check('languageIds',row.name+(row.active===false?'（已停用）':''),selected.has(row.id)).replace('name="languageIds"','name="languageIds" value="'+h(row.id)+'"')).join('')+'</div>',async f=>{
  const data=await api({op:'catalogLanguageFilterSave',mode:f.get('mode'),languageIds:f.get('mode')==='custom'?f.getAll('languageIds'):[],management:true});
  roomLanguages.data=data;roomLanguages.loadedAt=Date.now();filters.language='';roomSearch.generation++;render();toast('語言篩選已更新');
 });
}

function songToolbar(adminMode=false){scheduleRoomLanguages();return `<div class="toolbar"><input id="song-q" aria-label="搜尋歌曲" placeholder="歌名、歌手、語言、歌詞、標籤都能搜…" value="${h(filters.q)}"><label>語言<select id="song-language" aria-label="篩選歌曲語言">${languageOptionsHtml()}</select></label>${button('清除','clearFilters')}${adminMode?button('語言篩選設定','languageFilterSettings'):''}</div>${adminMode?'<div class="song-create-actions">'+button('＋新增歌曲','newSong','','primary')+button('批量匯入','import','songs')+'</div>':''}<details data-tags ${tagsExpanded?'open':''}><summary>標籤篩選（已選 ${filters.tags.length} 個）${filters.tags.length?' · '+h(filters.tags.slice(0,3).join('、')):' · 展開'}</summary><input type="search" data-tag-search placeholder="搜尋標籤" aria-label="搜尋標籤"><div class="chips search-tags" role="group" aria-label="標籤多選">${state.settings.tags.map(t=>`<label><input type="checkbox" data-filter-tag="${h(t)}" ${filters.tags.includes(t)?'checked':''}>${h(t)}</label>`).join('')}<small>可多選，符合任一標籤即可</small></div></details>`;}
function songStatusToolbar(){return '<div class="tabs song-visibility-tabs">'+button('歌曲','songVisibilityMode','visible',songVisibilityFilter==='visible'?'active':'')+button('隱藏歌曲','songVisibilityMode','hidden',songVisibilityFilter==='hidden'?'active':'')+'</div>'+(songVisibilityFilter==='hidden'?'<p class="muted">隱藏歌曲保留原資料，可恢復顯示；玩家歌本、搜尋與抽歌不會出現。</p>':'')+`<div class="toolbar song-admin-filters"><label>共同曲庫<select id="song-catalog-status"><option value="all">全部</option>${[['linked','已綁定'],['unlinked','未綁定'],['pending','待審核']].map(([value,label])=>`<option value="${value}" ${songCatalogStatusFilter===value?'selected':''}>${label}</option>`).join('')}</select></label></div>`;}
function renderBook(){const found=bookSearchResult(),p=found||paginate(filteredSongs(),'book',20);$('#app').innerHTML=card('🎵 歌本',`<div class="actions">${button('共同歌本','common-book','','tiny')}${session?button('♥ 我的最愛','myFavorites'):''}</div>`+songToolbar()+`<div id="song-list">${found?.loading?blank('搜尋中…'):songRows(p.rows)}${p.nav||''}</div>`,true);}
function renderCommonBook(){const rows=commonBook.rows||[];$('#app').innerHTML=`<section class="card common-book"><div class="section-head"><div><small>PA • PARTY</small><h1>共同歌本</h1><p class="muted">找一首歌，看看哪位主播、哪個版本會唱。</p></div>${button('回'+h(hostName())+'歌本','book')}</div><div class="toolbar common-book-filters"><input id="common-book-q" type="search" value="${h(commonBook.q)}" placeholder="搜尋歌名或歌手" aria-label="搜尋共同歌本">${nativeSelect('common-language','語言',[['','全部語言'],...commonBook.options.languages],commonBook.language)}${nativeSelect('common-performer','演唱類型',[['','全部類型'],...commonBook.options.performerTypes],commonBook.performerType)}${nativeSelect('common-version','版本類型',[['','全部版本'],...[...new Set(['original','cover','live',...commonBook.options.versionKinds])].map(k=>[k,({original:'原版',cover:'翻唱',live:'現場版',remix:'混音版',duet:'合唱版'})[k]||k])],commonBook.versionKind)}</div>${commonBook.error?'<p class="error">'+h(commonBook.error)+'</p>':''}<div id="common-book-results">${commonBook.loading?blank('搜尋中…'):rows.map(f=>`<article class="common-family"><h2>《${h(f.title)}》</h2>${(f.variants||[]).map(v=>`<div class="common-variant"><b>${h(v.versionLabel||'原版')} · ${h(v.artist)}</b>${(v.streamers||[]).map(r=>`<div class="common-streamer"><div>${button(h(r.name),'commonStreamer',r.slug,'tiny')}</div><div class="actions">${button('現點','commonRequest',r.songId,'tiny','data-slug="'+h(r.slug)+'" data-kind="live"')}${button('提歌','commonRequest',r.songId,'tiny','data-slug="'+h(r.slug)+'" data-kind="saved"')}</div></div>`).join('')}</div>`).join('')}</article>`).join('')||blank('沒有符合的共同歌曲')}</div><div class="pagination">${button('上一頁','commonBookPage','-1','tiny',commonBook.page?'':'disabled')}<small>第 ${commonBook.page+1} 頁 · 共 ${commonBook.total} 首共同歌曲</small>${button('下一頁','commonBookPage','1','tiny',(commonBook.page+1)*12<commonBook.total?'':'disabled')}</div></section>`;}
async function loadCommonBook(page=0){if(route!=='common-book')return;const generation=++commonBook.generation;commonBook.page=Math.max(0,page);commonBook.loading=true;renderCommonBook();if(demo){commonBook.rows=[];commonBook.total=0;commonBook.loading=false;renderCommonBook();return;}try{const response=await api({op:'catalogSongbook',q:commonBook.q,language:commonBook.language,performerType:commonBook.performerType,versionKind:commonBook.versionKind,limit:12,offset:commonBook.page*12});if(generation!==commonBook.generation)return;commonBook.rows=response.rows||[];commonBook.total=response.total||0;if(response.filters)commonBook.options={languages:response.filters.languages||[],performerTypes:response.filters.performerTypes||[],versionKinds:response.filters.versionKinds||[]};commonBook.error='';}catch(err){if(generation!==commonBook.generation)return;commonBook.error=err.message;commonBook.rows=[];}finally{if(generation===commonBook.generation){commonBook.loading=false;renderCommonBook();}}}
function commonBookDestination(slug,songId=null,kind=null){const u=new URL(location.href);u.searchParams.set('streamer',slug);u.searchParams.delete('adminTab');u.searchParams.delete('tab');if(songId){u.searchParams.set('commonRequest',songId);u.searchParams.set('commonKind',kind);}else{u.searchParams.delete('commonRequest');u.searchParams.delete('commonKind');}u.hash=songId?'book':'home';location.href=u.href;}
async function commonBookRequest(slug,songId,kind){if(slug!==streamerSlug){commonBookDestination(slug,songId,kind);return;}await go('book');await requestSong(songId,kind);}
function renderGallery(){const rows=state.cards.filter(c=>galleryFilter==='history'||galleryFilter==='current'&&currentCards().includes(c)||galleryFilter==='expired'&&c.expiresAt&&timeValue(c.expiresAt)<=Date.now()+offset);$('#app').innerHTML=card('🖼️ 卡片牆',`<div class="tabs">${[['current','目前卡片'],['history','歷史卡片'],['expired','已過期']].map(([id,label])=>button(label,'galleryFilter',id,galleryFilter===id?'active':'')).join('')}</div><div class="gallery">${rows.map(photoHtml).join('')||blank()}</div>`,true);}
function playerTabs(id,manager=false){const p=state.players.find(x=>x.playerId===id);if(!p)return blank('找不到玩家');const qs=state.queue.filter(q=>q.playerId===id),done=qs.filter(q=>q.status==='completed'&&!q.test&&!q.selfProvided),cs=state.crowns.filter(c=>c.playerId===id),cards=state.cards.filter(c=>c.playerId===id),wishes=state.wishes.filter(w=>w.playerId===id),names=[['overview',manager?'基本資料':'總覽'],['ledger','存歌'],['queue','目前點歌／歷史'],['crowns','冠歌'],['cards','卡片'],['wishes','許願'],...(!manager&&session?.playerId===id?[['favorites','♥ 我的最愛']]:[])];let body='';if(subtab==='overview'){body=`${(p.quotaRights||[]).map(right=>'<p class="exclusive-quota" style="color:#ffd45c">👑 專屬'+h(right.streamer_name)+'提歌權 +'+right.extra_quota+'</p>').join('')}<div class="stats"><div class="stat">💾 存歌<b>${storedBalanceHtml(id)}</b></div><div class="stat">🎤 已唱<b>${qs.filter(q=>q.status==='completed'&&!q.test).length}</b></div><div class="stat">👑 冠歌<b>${cs.length}</b></div><div class="stat">🖼️ 卡片<b>${cards.length}</b></div></div><div class="notice">${h(p.certification?'🐯 平台認證：'+p.certification:say('center'))}</div><div class="chips achievement-badges">${(manager?achievements(state,id,clock()):state.badges||[]).slice(0,3).map(x=>`<span class="tag">${h(x)}</span>`).join('')}</div><h3 style="margin-top:20px">我最常聽的歌</h3><div id="listening-overview" data-player="${h(id)}" data-management="${manager}">${listeningOverviewHtml(id,manager)}</div><div class="notice">ID：${h(p.ids.join('、')||'尚未填寫')}<br>曾用名：${h(p.names.join('、'))}</div>${manager?button('編輯玩家／密碼','editPlayer',id)+button('專屬提歌權','editExtraQuota',id)+(isSuperAdmin()?button(p.archived?'恢復玩家':'封存玩家',p.archived?'playerRestore':'playerArchive',id,'tiny danger',playerArchiveView.pending.size?'disabled':''):''):button('我的名稱與密碼','self')}`;}if(subtab==='favorites'&&!manager&&session?.playerId===id)body='<div id="favorites-panel">'+favoritesPanelHtml()+'</div>';if(subtab==='ledger')body=ledgerRows(id,manager);if(subtab==='queue')body='<h3>我的目前操作</h3>'+queueRows(qs.filter(q=>['pending','waiting'].includes(q.status)),manager)+'<h3>歷史紀錄</h3>'+queueRows(qs.filter(q=>!['pending','waiting'].includes(q.status)),manager);if(subtab==='crowns')body=crownsHtml(cs,manager);if(subtab==='cards')body=`<div class="gallery">${cards.map(photoHtml).join('')||blank()}</div>`;if(subtab==='wishes')body=wishRows(wishes,manager);return `<h2>${h(p.name)}</h2><div class="tabs">${names.map(([k,n])=>button(n,'subtab',k,subtab===k?'active':'')).join('')}</div>${body}`;}
function renderCenter(){const p=me();$('#app').innerHTML=card('👤 玩家中心',p?playerTabs(p.playerId):blank('請先登入'),true);}
function ledgerRows(id,manager){let rows=state.ledger.filter(l=>(!id||l.playerId===id)&&venuePolicyLedgerPool(l)===venuePolicySettings(state.settings).current_space);if(!id&&ledgerQuery){const ids=playerSearch(state,ledgerQuery,true).map(x=>x.playerId);rows=rows.filter(l=>ids.includes(l.playerId));}rows.sort((a,b)=>(timeValue(b.at)||0)-(timeValue(a.at)||0));const p=paginate(rows,'ledger');return `${manager?`<div class="toolbar">${venueSwitch()}${!id?`<input id="ledger-query" value="${h(ledgerQuery)}" placeholder="搜尋玩家名稱、ID、曾用名" aria-label="存歌玩家搜尋">`:''}${button('新增存歌','addLedger',id||'')}</div><small>最近 · 每頁 10 筆</small>`:''}<div id="ledger-results">${p.rows.map(l=>`<div class="song admin-row"><div class="info"><b>${manager?h(playerName(l.playerId))+' · ':''}<span class="${l.amount>=0?'positive':'negative'}">${l.amount>=0?'+':''}${l.amount} 首</span></b><small>${time(l.at)} · ${h(l.note)}${venuePolicySettings(state.settings).radio_enabled?' · '+venueName(venuePolicyLedgerPool(l)):''}</small></div>${manager?`<div class="actions">${l.allocationSettlement?'<span class="tag">系統結算・保留紀錄</span>':button('編輯','editLedger',l.id)}${l.amount>0&&!l.queueId&&!l.conversion?button('分配','allocate',l.id):''}${l.allocationSettlement?'':button('刪除','deleteLedger',l.id,'tiny danger')}</div>`:''}</div>`).join('')||blank()}${p.nav}</div>`;}
function queueRows(rows,manager,compact=false){const history=rows.every(q=>!['waiting','pending'].includes(q.status));if(history)rows=[...rows].sort((a,b)=>timeValue(b.effective_at||b.completedAt||b.at)-timeValue(a.effective_at||a.completedAt||a.at));const p=paginate(rows,history?'queue-history':'queue');return p.rows.map(q=>{const active=['waiting','pending'].includes(q.status),confirmed=queueConfirmed(q),prepared=queuePrepared(q),title=q.items?.map(i=>i.title+(i.performances>1?' ×'+i.performances:'')).join(' ＋ ')||q.title;const lyricItems=q.items?.length?q.items:[q],hasLyrics=lyricItems.some(i=>{const row=song(i.songId);return !!(row?.hasLyrics??String(row?.lyrics||'').trim());});const primary=q.status==='pending'?button('確認禮物','queueOp',q.id,'primary','data-op="approve"'):q.awaitingAcknowledgment?button('確認收到','queueOp',q.id,'primary','data-op="acknowledge"'):q.awaitingPreparation?button('設定準備時間','stage',q.id,'primary'):q.status==='waiting'?button('🎤 完成演唱','queueOp',q.id,'primary','data-op="complete"'):'';return `<article class="song admin-row queue-row ${compact?'queue-compact':''}">${manager?'<input type="checkbox" aria-label="選取 '+h(q.title)+'" data-queue-select="'+h(q.id)+'" '+(selectedQueue.has(q.id)?'checked':'')+'>':''}<div class="info">${compact?`<div class="queue-track"><b class="queue-title">${h(title)}</b><span class="queue-artist">${q.artist?'˙'+h(q.artist):''}</span></div>`:`<b class="queue-title">${h(title)}</b><span class="queue-artist">${h(q.artist||'')}</span><strong class="queue-player">${h(q.kind==='self'?'主播自帶':playerName(q.playerId))}</strong>`}<div class="queue-state" data-preparation="${h(q.id)}">${active?h(queuePreparation(q,clock())):statusName[q.status]}</div><small>${compact?`<strong class="queue-player">${h(q.kind==='self'?'主播自帶':playerName(q.playerId))}</strong> · `:''}${q.kind==='self'?'主播自帶':q.kind==='saved'?'提歌':'現點'} · ${time(q.effective_at||q.at)}${venuePolicyHistoryVenue(q)?' · '+venueName(q.venue):''}${q.selfProvided?' · 自帶（不計熱門／常聽）':''}${q.test?' · 測試':''}</small>${q.requestNote?'<small class="queue-request-note">💬 '+h(q.requestNote)+'</small>':''}</div>${manager?'<div class="queue-controls"><div class="queue-primary">'+primary+'</div>'+(prepared?'<div class="queue-secondary">'+(hasLyrics?button('查看歌詞','queueLyrics',q.id):'')+button('編輯／換歌','editQueue',q.id)+button('準備時間','stage',q.id)+'</div>':'')+'<details class="queue-more"><summary>更多</summary>'+(!active&&hasLyrics?button('查看歌詞','queueLyrics',q.id):'')+(active?button('取消','queueOp',q.id,'tiny','data-op="cancel"'):'')+(prepared?button('↑','move',q.id,'tiny','data-step="-1"')+button('↓','move',q.id,'tiny','data-step="1"')+(q.kind==='live'?button('未唱→存歌','queueOp',q.id,'tiny','data-op="store"'):''):'')+button(active?'時間／備註':'修改時間','recordTime',q.id,'tiny','data-table="queue"')+(q.allocation_id&&!active?'':button(active?'移出待播':'移除紀錄','queueOp',q.id,'tiny danger','data-op="delete"'))+(q.kind==='saved'?'<small>扣存歌來源：'+venueName(venuePolicyConsumedPool(q))+'</small>':q.allocation_id?'<small>分配存歌來源：'+venueName(q.allocation_storage_pool||'shengma')+'</small>':'')+(q.note?'<p>備註：'+h(q.note)+'</p>':'')+'</details></div>':active&&q.playerId===session?.playerId?button('取消','cancelOwn',q.id):''}</article>`;}).join('')+p.nav;}
function prepareQueue(id,operation){const q=state.queue.find(q=>q.id===id);if(!q)return;modal(operation==='approve'?'確認禮物 · 準備時間':operation==='acknowledge'?'確認收到 · 準備時間':'設定準備時間','<h3>'+h(q.title)+'－'+h(q.artist)+'</h3>'+field('preparationMinutes','準備時間（分鐘）',q.preparationMinutes??0,'number','min="0" max="120" step="1" required')+'<p>0 分鐘＝已準備好，立即通知玩家；1～120 分鐘會顯示倒數，到時通知玩家。</p>',async f=>dispatch('queue',{id,operation,preparationMinutes:f.get('preparationMinutes')}));}

function wishRows(rows,manager){const p=paginate(rows,'wishes');return p.rows.map(w=>`<div class="song"><div class="info"><b>${h(w.title)}－${h(w.artist)}</b><small>${manager?h(playerName(w.playerId))+' · ':''}${time(w.at)} · ${h(w.note)}</small><div class="tag">${h(w.status)}</div>${w.status==='已學會'?'<p class="positive">✨ 願望成真！這首'+h(hostName())+'學會啦～</p>':''}${w.url?`<a href="${h(w.url)}" target="_blank" rel="noopener">歌曲連結 ↗</a>`:''}</div>${manager?button('處理','editWish',w.id)+button('時間','recordTime',w.id,'tiny','data-table="wishes"'):''}</div>`).join('')+p.nav;}
const adminTabs=[['queue','🎤 待播'],['songs','🎵 歌曲'],['players','👤 玩家'],['ledger','💾 存歌'],['crowns','👑 冠歌'],['cards','🖼️ 卡片'],['wishes','🌟 許願池'],['stats','📈 統計'],['events','📜 操作歷史'],['settings','⚙️ 設定']];
function renderAdmin(){if(tab==='dashboard')tab='queue';let body='';
 if(tab==='queue')body=`<div class="queue-heading"><h2>🎤 待播</h2><div class="queue-live-tools">${venueSwitch()}<div class="live-shortcuts">${[['空閒','空閒中','#79d5b0'],['忙碌','忙碌中','#f299ab'],['準備','準備中','#e9b975'],['暫停','暫停點歌','#c4a5ed']].map(([label,value,color])=>button('<span class="queue-status-dot" aria-hidden="true" style="background:'+color+'"></span>'+label,'status',value,state.settings.status===value?'tiny active':'tiny')).join('')}</div></div></div><div class="queue-toolbar">${button('加入待播歌曲','onBehalf')}<div class="tabs">${button('待播','queueMode','active',!queueHistory?'active':'')}${button('歷史','queueMode','history',queueHistory?'active':'')}</div></div><details class="queue-bulk"><summary>批次操作</summary>${button('全選目前列表','selectQueue')}${button('取消選取','clearQueueSelection')}${button('刪除已選','deleteSelectedQueue','','tiny danger')}</details>${queueRows(state.queue.filter(q=>queueHistory?!['pending','waiting'].includes(q.status):['pending','waiting'].includes(q.status)),true,true)}<footer class="queue-summary">${(()=>{const totals=stats(state,clock());return `<div class="queue-totals">收到 ${totals.received} ｜ 唱了 ${totals.sung} ｜ 存了 ${totals.saved}</div>`;})()}<small>歌曲 ${state.songs.length} · 玩家 ${state.players.length} · 冠歌 ${state.crowns.length}</small></footer>`;

 if(tab==='songs')body=songToolbar(true)+'<div class="actions">'+button('新練歌曲排序','newPracticeManage')+'</div>'+songStatusToolbar()+`<details class="tag-management"><summary>管理本主播標籤</summary><div class="chips">${state.settings.tags.map(t=>button(h(t)+' ×','deleteTag',t)).join('')}${button('＋標籤','addTag')}</div></details><div id="song-batch-bar">${songBatchBar()}</div><div id="song-list">${adminSongList()}</div>`;
 if(tab==='players'){if(selectedPlayer)body=button('← 玩家列表','backPlayers')+playerTabs(selectedPlayer,true);else body='<div id="player-management">'+playerManagementPanel()+'</div>';}
 if(tab==='ledger')body=ledgerRows(null,true);
 if(tab==='crowns')body=`<div class="toolbar">${button('新增冠歌','editCrown')}${button('批量匯入','import','crowns')}${button('如何冠歌？','crownHelp')}</div>${crownsHtml(state.crowns,true)}`;
 if(tab==='cards')body=`<div class="toolbar">${button('上傳照片卡','editCard')}</div><div class="gallery">${state.cards.map(c=>`<div>${photoHtml(c)}${button('編輯','editCard',c.id)}${button('刪除','deleteCard',c.id,'tiny danger')}</div>`).join('')||blank()}</div>`;
 if(tab==='wishes')body=wishRows(state.wishes,true);
 if(tab==='stats')body=`<label>選擇直播場次<input id="stats-day" type="date" value="${liveDay(clock())}"></label><div id="stats-result">${statsHtml(stats(state,clock()))}</div><p class="muted">19:00 切場。收到＝新增存歌（不含初始／歷史存歌）＋確認現點；唱了＝完成演唱次數（包含提歌）；存了＝本場收到扣除本場已唱用額，最低為 0。測試玩家不列入統計。</p>`;
 if(tab==='events'){body='<p class="muted">重要操作永久保留，依登記時間由新到舊。可展開核對修改前後資料。</p><div id="event-list">讀取中…</div>';setTimeout(loadEvents,0);}if(tab==='settings')body=settingsHtml();
 if(tab==='catalog'&&admin){if(!isSuperAdmin()&&!['approved','issues'].includes(catalogView.section))catalogView.section='approved';body=catalogReviewHtml();}
 $('#app').innerHTML=`<div class="admin-banner"><b>🔐 ${isSuperAdmin()?'PA Party總裁 · ':''}${h(hostName())}的管理後台</b><div class="actions">${button(h('回'+hostName()+'首頁'),'home')}${button('修改密碼','changeManagerPassword')}${button('登出管理','adminLogout')}</div></div><div class="streamer-toolbar"><details class="room-picker"><summary>目前管理主播：${h(state.currentStreamer.display_name)}</summary><input type="search" data-room-filter placeholder="搜尋主播"><div class="room-options">${state.streamers.map(r=>button(h(r.display_name)+(r.active?'':'（未開放）'),'switchStreamer',r.slug)).join('')}</div></details>${button('新增主播','editStreamer')}${button('編輯主播','editStreamer',state.currentStreamer.id)}${isSuperAdmin()?button('主播帳號與密碼','streamerAccounts'):''}</div><div class="tabs">${[...adminTabs,['catalog','🎼 共同曲庫管理']].map(([id,label])=>button(label,'adminTab',id,tab===id?'active':'')).join('')}</div><section class="card">${body}</section>`;if(!isSuperAdmin()){for(const el of document.querySelectorAll('[data-act=editStreamer],[data-act=draft],[data-act=publish],[data-act=backup],[data-act=migrate],[data-act=import][data-id=players]'))el.remove();document.querySelector('.room-picker')?.remove();}if(tab==='catalog'&&!catalogView.loaded&&!catalogView.loading)setTimeout(loadCatalogReview,0);
}
function editHome(){openHomeEditor({home:state.settings.home,room:state.currentStreamer,modal,dispatch,demo,toast,upload:async file=>(await api({op:'upload',image:await compress(file,1800),mime:'image/webp'})).url});}
function applyHomeTheme(){const root=document.documentElement;if(!state.settings.home){delete root.dataset.homeTheme;return;}root.dataset.homeTheme='custom';for(const [k,v] of Object.entries(themePalette(state.settings.home.color)))root.style.setProperty('--home-'+k,v);}
function settingsHtml(){return `<div class="notice ${draft?'warning':''}">${demo?'預覽測試：資料只存在這台裝置':draft?'📝 草稿模式：只存在這台裝置':'☁️ 正式同步模式'}</div><div class="actions">${button('開始草稿測試','draft')}${button('匯出備份','backup')}${draft?button('正式同步','publish','','primary')+button('離開草稿','leaveDraft'):''}</div><hr><h3>首頁外觀與內容</h3><p class="muted">主題色、主圖、卡片顯示與排序、本日狀態欄位</p>${button('自訂首頁','editHome','','primary')}<hr><h3>直播與價格</h3><p class="muted">${h(state.settings.opening)} · 試音 ${money(state.settings.audition)} · 一般現點 ${money(state.settings.livePrice)}＋雙費 ${money(state.settings.liveDouble)}</p>${button('編輯設定與說明書','editSettings')}${button('存歌方案','editPlans')}${button('冠歌卡別價格','editTiers')}${isSuperAdmin()?'<hr><h3>系統工具／資料檢查</h3>'+button(catalogView.scanning?'掃描中…':catalogView.scanComplete?'重新掃描既有歌本':catalogView.scanCursor?'掃描下一批 100 首':'掃描既有歌本候選','catalogScan','','tiny',catalogView.scanning?'disabled':'')+'<p class="muted">已檢查 '+catalogView.scanTotal+' 首'+(catalogView.scanComplete?'，本輪完成':'；每批最多 100 首，只建立待審候選。')+'</p>'+(state.schemaVersion<3?button('讀取舊版資料並核對','migrate'):'')+(state.migrationIssues?.length?'<details class="notice warning"><summary>資料移轉待核對 '+state.migrationIssues.length+' 項</summary>'+state.migrationIssues.map(h).join('<br>')+'</details>':'<small>沒有待核對的舊版資料</small>'):''}`;}
function render(){if(playerArchiveView.open&&(!isSuperAdmin()||playerArchiveIdentity()!==playerArchiveView.identity)){playerArchiveView.open=false;$('#dialog')?.close();}applyHomeTheme();header();if(route==='admin'&&admin)renderAdmin();else if(route==='common-book')renderCommonBook();else if(route==='book')renderBook();else if(route==='center'&&session)renderCenter();else if(route==='gallery')renderGallery();else renderHome();if(route==='admin'&&admin&&tab==='players'&&!selectedPlayer)loadPlayerManagement();loadVisibleFavoriteFlags();loadFavorites();loadListeningOverview();}

async function loginDialog(){modal('👤 玩家登入','<label>名稱、ID 或曾用名<input id="login-query" placeholder="找找自己"></label><div id="login-results"></div>');}
async function chooseLogin(id){const result=demo?full.players.find(p=>p.playerId===id):(await api({op:'search',query:id})).players.find(p=>p.playerId===id);if(!result)return;modal('登入 '+result.name,`${select('loginId','本次使用的 ID',result.ids.length?result.ids.map(x=>[x,x]):[['','沒有平台 ID']],result.ids[0])}${result.hasPassword||result.password?field('password','玩家密碼','','password','autocomplete="current-password"'):''}`,async f=>{let token='demo';if(!demo)token=(await api({op:'login',playerId:id,loginId:f.get('loginId'),password:f.get('password')||''})).token;else if(String(result.password||'')!==String(f.get('password')||''))throw new Error('玩家密碼不正確');const identity={playerId:id,loginId:f.get('loginId')||'',role:'player',token};session=deviceLogin?await deviceLogin.remember(identity,{streamer:streamerSlug}):identity;put('player',session);if(entryPending){route='home';await openSpaceEntry();return;}await go('home');});}
async function adminLogin(){
 if(entryPending&&!demo&&!legacyEntryRoomsLoaded){const response=await deviceTransport({op:'entryLegacyRooms'});state.streamers=response.rooms;legacyEntryRoomsLoaded=true;}
 modal('🔐 管理入口',nativeSelect('mode','登入身分',[['streamer','主播管理'],['super','PA Party總裁']],'streamer')+'<div data-login-room>'+nativeSelect('streamer','選擇主播',state.streamers.map(r=>[r.slug,r.display_name]),streamerSlug)+'</div>'+(demo?'<p>本機測試模式</p>':field('password','密碼','','password','required autocomplete="current-password"')),async f=>{
 const mode=f.get('mode'),slug=mode==='streamer'?f.get('streamer'):undefined;
 const auth=demo?{token:'demo',role:mode==='super'?'super_admin':'streamer_admin',streamerSlug:slug,expiresIn:43200,legacy:true}:await api({op:mode==='super'?'adminLogin':'streamerLogin',streamer:slug,password:f.get('password')});
 const identity={...auth,until:Date.now()+43200000,accessUntil:Date.now()+(auth.expiresIn-60)*1000};admin=deviceLogin?await deviceLogin.remember(identity,{streamer:slug||streamerSlug}):identity;draft=null;put('admin',admin);
 if(entryPending){route='admin';await openSpaceEntry();return;}
 if(admin.role==='streamer_admin'&&admin.streamerSlug!==streamerSlug){const u=new URL(location.href);u.searchParams.set('streamer',admin.streamerSlug);u.hash='admin';location.href=u.href;return;}
 await go('admin');toast('已登入，點「啟用通知音效」開始提醒');
 });
 $('#modal-form [name=mode]').addEventListener('change',e=>{const superMode=e.target.value==='super';$('#dialog [data-login-room]').hidden=superMode;$('#dialog [name=streamer]').disabled=superMode;const password=$('#dialog [name=password]');if(password)password.value='';});
}
function changeManagerPassword(){
 const min=isSuperAdmin()?8:4;
 modal('修改'+(isSuperAdmin()?'PA Party總裁':'主播')+'密碼',field('currentPassword','目前密碼','','password','required autocomplete="current-password"')+field('newPassword','新密碼（至少 '+min+' 字）','','password','required minlength="'+min+'" maxlength="72" autocomplete="new-password"')+field('confirmPassword','再輸入一次新密碼','','password','required autocomplete="new-password"')+'<p class="muted">儲存後，此管理身分需重新登入。</p>',async f=>{
 if(f.get('newPassword')!==f.get('confirmPassword'))throw Error('兩次新密碼不一致');if(demo)throw Error('請在正式登入後修改密碼');
 await api({op:'changeManagerPassword',management:true,currentPassword:f.get('currentPassword'),newPassword:f.get('newPassword')});admin=null;draft=null;put('admin',null);await go('home');toast('密碼已更新，請重新登入管理');
 });
}
function shortSongOptions(item){if(Number(item.creditCost)!==0.5)return '';const mode=item.shortMode||'repeat';return '<p class="notice">此歌較短；唱兩次或搭配兩首，合計扣 1 首。</p><input type="search" data-short-filter placeholder="搜尋可搭配的歌曲">'+nativeSelect('pairSongId','演唱方式',[...(mode!=='pair'?[['','這首唱兩次']]:[]),...(item.pairSongIds||[]).map(id=>song(id)).filter(Boolean).map(x=>[x.songId,'搭配：'+x.title+'－'+x.artist])],'');}
async function requestSong(id,kind,selfProvided=false){if(!session)return loginDialog();const item=song(id);if(!item)return toast('歌曲已更新');const c=crownFor(state,id,clock()),other=c&&c.playerId!==session.playerId;if(other)kind='live';const cost=Number(item.creditCost)===0.5?1:Number(item.creditCost||1);let insufficient=false;if(kind==='saved')try{venuePolicySavedSnapshot(state,session.playerId,cost);}catch{insufficient=true;}if(insufficient){modal('沒有可提的存歌','<p>目前沒有足夠的存歌可提這首歌。</p><div class="actions">'+button('前往現點','request',id,'primary','data-kind="live"')+'</div>');return;}const liveHelp=button('點歌教學','prices','','tiny');modal(kind==='saved'?'🎤 確認提歌':'🎁 確認現點','<h3>'+h(item.title)+'－'+h(item.artist)+'</h3>'+shortSongOptions(item)+(kind==='saved'?'<p>此歌曲會扣 '+cost+' 首存歌，並占用 '+cost+' 首本小時提歌額度。完成演唱才扣存歌，待唱先保留。</p>':other?'<p>現點費用：'+money(c.price)+' 探鑽；另需雙費：'+money(state.settings.liveDouble??500)+' 探鑽</p>'+check('gift','我已確認禮物價格')+liveHelp:'<p>給歌手 '+money(state.settings.livePrice)+' 探鑽＋雙費 '+money(state.settings.liveDouble)+' 探鑽</p>'+check('gift','我已確認禮物價格')+liveHelp)+field('requestNote','想說的話（選填，最多 30 字）','','text','maxlength="60" autocomplete="off"'),async f=>{const data={songId:id,kind,selfProvided,pairSongId:f.get('pairSongId')||'',giftConfirmed:f.has('gift'),requestNote:f.get('requestNote')||''};try{await dispatch('request',data);toast(say('success'));}catch(e){if(kind==='saved'){if((e.message.includes('本小時真的滿')||e.message.includes('提歌額度不足'))&&!demo)try{await api({op:'failedRequest',songId:id,pairSongId:data.pairSongId});}catch{}if((e.message.includes('本小時真的滿')||e.message.includes('提歌額度不足'))||e.message.includes('存歌袋空空')||e.message.includes('可用存歌不足'))e.liveSongId=id;}throw e;}});}

function crownHelp(){modal('👑 如何冠歌？',`<div class="table-wrap"><table><thead><tr><th>卡別</th><th>辦卡給歌手</th><th>辦卡雙費</th><th>其他玩家現點</th><th>期限</th></tr></thead><tbody>${state.settings.tiers.map(t=>`<tr><td>${h(t.name)}</td><td>${money(t.fee)}</td><td>${money(state.settings.crownDouble)} × 2</td><td>${money(t.price)}／首＋雙費 ${money(state.settings.liveDouble??500)}</td><td>${t.months?t.months+' 個月':'永久'}</td></tr>`).join('')}</tbody></table></div><div class="notice">🎤 給歌手對應數值禮物<br>💰 辦卡雙費：聲瑪樂團 ${money(state.settings.crownDouble)}＋2號位主持 ${money(state.settings.crownDouble)}，兩筆都需要。<br>選歌曲 → 選卡別 → 付辦卡費＋雙費 → 確認後生效 ✨</div><p class="muted">金額皆為探鑽。點歌雙費與一般現點相同，為 ${money(state.settings.liveDouble??500)}；辦卡雙費另計。冠歌主人照一般規則；其他玩家在有效期間內只能依卡別現點。</p>`);}
