function editCrown(id){const c=state.crowns.find(c=>c.id===id)||{},tier=state.settings.tiers.find(t=>t.name===c.tier)||state.settings.tiers[0];modal('👑 冠歌管理',`<div class="form-grid">${select('playerId','冠歌主人',playerOptions(c.playerId),c.playerId)}${select('songId','歌曲',state.songs.map(s=>[s.songId,s.title+'－'+s.artist]),c.songId)}${select('tier','卡別',state.settings.tiers.map(t=>t.name),tier.name)}${field('fee','辦卡給歌手',c.fee??tier.fee,'number','min="0"')}${field('price','其他玩家現點',c.price??tier.price,'number','min="0"')}${field('double','辦卡雙費（每人）',c.double??state.settings.crownDouble,'number','min="0"')}${field('months','期限月數（0＝永久）',c.months??tier.months,'number','min="0"')}${area('note','備註',c.note||'')}</div>${c.activatedAt?`<div class="notice">生效：${time(c.activatedAt)}<br>到期：${c.expiresAt?time(c.expiresAt):'永久'}</div>`:`<div class="notice">先存為待確認；三筆款項齊了，再勾選生效。</div>${check('singerPaid','已收到辦卡給歌手費用')}${check('bandPaid','已收到聲瑪樂團費用')}${check('hostPaid','已收到2號位主持費用')}${check('activate','確認現在生效，從現在開始計算期限')}`}${c.id?button('刪除冠歌','deleteCrown',c.id,'tiny danger'):''}`,async f=>dispatch('crown',{...formData(f),id:c.id,activate:f.has('activate'),singerPaid:f.has('singerPaid'),bandPaid:f.has('bandPaid'),hostPaid:f.has('hostPaid')}));$('#dialog select[name=tier]').onchange=e=>{const t=state.settings.tiers.find(t=>t.name===e.target.value);for(const k of ['fee','price','months'])$('#dialog [name='+k+']').value=t[k];};}
async function compress(file,max=1400){if(!file||!file.type.startsWith('image/'))throw new Error('請選圖片');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),ratio=Math.min(1,max/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/webp',.82).split(',')[1];}
function editCard(id){const c=state.cards.find(c=>c.id===id)||{};modal('🖼️ 照片卡片',`${field('file','上傳照片（自動壓縮、縮圖）','','file','accept="image/*"')}${select('playerId','綁定玩家（選填）',[['','不綁定'],...playerOptions(c.playerId).slice(1)],c.playerId)}${area('description','簡述',c.description||'')}${field('startsAt','開始時間',dateInput(c.startsAt||clock()),'datetime-local','required')}${field('expiresAt','到期時間（留空永久）',dateInput(c.expiresAt),'datetime-local')}`,async f=>{let url=c.url,thumbnail=c.thumbnail;const file=f.get('file');if(file?.size){if(demo)throw new Error('圖片上傳需連接 Supabase，預覽不存 Base64 圖片');url=(await api({op:'upload',image:await compress(file),mime:'image/webp'})).url;thumbnail=(await api({op:'upload',image:await compress(file,480),mime:'image/webp'})).url;}await dispatch('card',{id:c.id,url,thumbnail,playerId:f.get('playerId'),description:f.get('description'),startsAt:isoInput(f.get('startsAt')),expiresAt:isoInput(f.get('expiresAt'))});});}
function editWish(id){const w=state.wishes.find(w=>w.id===id);modal('處理許願',`<h3>${h(w.title)}－${h(w.artist)}</h3>${select('status','狀態',['收到','考慮中','學習中','已學會','暫不學'],w.status)}${check('addSong','已學會，加入曲庫（已有同歌則連動）')}`,async f=>dispatch('wishAdmin',{id,status:f.get('status'),addSong:f.has('addSong')}));}
function editSettings(){const s=state.settings;modal('⚙️ 設定',`<div class="form-grid">${field('opening','開廳時間',s.opening)}${field('hourlyLimit','每小時提歌上限',s.hourlyLimit,'number','min="0"')}${field('audition','試音價格',s.audition,'number')}${field('livePrice','一般現點給歌手',s.livePrice,'number')}${field('liveDouble','點歌雙費（一般／冠歌共用）',s.liveDouble,'number')}${field('crownDouble','辦卡雙費（每人）',s.crownDouble,'number')}${check('radio_enabled','啟用電台（與聲瑪共用歌本及提歌額度）',s.radio_enabled===true)}${area('manual','📖 說明書（支援換行、Emoji）',s.manual)}</div>`,async f=>dispatch('settings',{...formData(f),radio_enabled:f.has('radio_enabled')}));}
function editPrices(kind){const rows=state.settings[kind];modal(kind==='tiers'?'冠歌卡別價格':'存歌方案',rows.map((p,i)=>`<h3>${h(p.name)}</h3><div class="form-grid">${field('name'+i,'名稱',p.name)}${Object.keys(p).filter(k=>k!=='name').map(k=>field(k+i,({fee:'給歌手',price:'其他玩家現點',months:'期限月數（0永久）',amount:'首數',double:'雙費'})[k],p[k],'number','min="0"')).join('')}</div>`).join(''),async f=>dispatch('settings',{[kind]:rows.map((p,i)=>Object.fromEntries(Object.keys(p).map(k=>[k,k==='name'?f.get(k+i):Number(f.get(k+i))])))}));}
function importDialog(kind){importKind=kind;modal('批量匯入',`<div class="notice">${kind==='players'?'主要名稱｜平台ID｜其他ID｜曾用名稱｜存歌｜密碼｜備註｜平台認證':kind==='songs'?'歌名｜歌手｜語言｜歌手類型｜標籤｜新練｜主播碎碎念':'歌曲｜歌手｜冠歌主人｜卡別｜生效時間｜備註'}<br>一行一筆。先檢查，再匯入。冠歌匯入一律待確認。</div><textarea id="import-text" aria-label="匯入資料" rows="8"></textarea><div class="actions">${button('檢查資料','previewImport','','primary')}</div><div id="import-preview"></div>`);}
async function preview(){importText=$('#import-text').value;importRows=previewImport(state,importKind,importText);if(importKind==='songs'&&!demo&&!draft){const rows=importRows.filter(r=>!r.error).map(r=>({line:r.line,title:r.data.title,artist:r.data.artist,cat:r.data.cat}));for(let i=0;i<rows.length;i+=100){const matches=await api({op:'catalogImportMatches',rows:rows.slice(i,i+100),management:true});for(const m of matches||[]){const r=importRows.find(x=>x.line===m.line);if(r)r.catalogMatches=m;}}}$('#import-preview').innerHTML=`<div class="notice">${importKind==='songs'?'共同歌曲只顯示候選；請手動勾選或指定版本，未選會正常匯入為未綁定。':'更新玩家時保留原存歌餘額；數量異動請用存歌紀錄。'}</div>${importKind==='songs'?button('全選明確匹配','selectAllImportMatches'):''}${importRows.map((r,i)=>{const m=r.catalogMatches,one=m?.total===1&&m.matches?.length===1&&(!r.data.cat||m.matches[0].language===r.data.cat);return `<div class="song import-review-row"><div class="info"><b>第 ${r.line} 筆 · ${h(r.data.name||r.data.title||song(r.data.songId)?.title||'冠歌')}</b><small class="${r.error?'error':''}">${h(r.error||(r.match?'疑似重複，請選更新或跳過':'可新增'))}</small>${importKind==='songs'&&!r.error?(one?`<label><input type="checkbox" data-import-link="${i}" value="${h(m.matches[0].variantId)}"> 綁定明確匹配：${h([m.matches[0].title,m.matches[0].artist,m.matches[0].versionLabel||'原版'].join(' · '))}</label>`:m?.total?`<label>可能版本（請自行選擇）<select data-import-variant="${i}"><option value="">先不綁定</option>${(m.matches||[]).map(v=>`<option value="${h(v.variantId)}">${h([v.title,v.artist,v.versionLabel||'原版',v.language].join(' · '))}</option>`).join('')}</select></label>${m.total>m.matches.length?'<small>更多版本請匯入後在編輯歌曲中搜尋。</small>':''}`:'<small>共同曲庫無明確匹配；匯入後可再補綁。</small>'):''}</div><select data-import-row="${i}" aria-label="第 ${r.line} 筆處理">${r.error?'<option value="skip">跳過錯誤</option>':r.match?'<option value="skip">跳過</option><option value="update">更新</option>':'<option value="add">新增</option><option value="skip">跳過</option>'}</select></div>`;}).join('')}${button('確認匯入','applyImport','','primary')}`;}
async function executeImport(){const choices=importRows.map((_,i)=>$('#dialog [data-import-row="'+i+'"]').value),beforeIds=new Set(state.songs.map(s=>s.songId));let linked=0,linkError='';if(demo||draft){if(draft){if(!draft.journal)throw Error('舊草稿請先下載備份，再重新建立');const recorded=recordRoomDraftImport(full,draft.journal,importKind,importText,choices,{role:'admin'},clock());full=recorded.state;draft.journal=recorded.journal;}else full=applyImport(full,importKind,importRows,choices,{role:'admin'},clock(),streamerSlug);if(draft){draft.state=full;put('draft',draft);}else put('demo',full);state=publicView(full,actor(),clock(),streamerSlug);}else{const r=await api({op:'import',revision:state.revision,kind:importKind,text:importText,choices});state={...state,...r.state};if(importKind==='songs'){const selections=importRows.flatMap((row,i)=>{if(choices[i]==='skip')return [];const variantId=$('#dialog [data-import-link="'+i+'"]:checked')?.value||$('#dialog [data-import-variant="'+i+'"]')?.value;if(!variantId)return [];const target=choices[i]==='update'?row.match:state.songs.find(s=>!beforeIds.has(s.songId)&&s.title===row.data.title&&s.artist===row.data.artist);return target?[{songId:target.songId,variantId,title:row.data.title,artist:row.data.artist}]:[];});if(selections.length)try{for(let i=0;i<selections.length;i+=100){const result=await api({op:'catalogImportLink',selections:selections.slice(i,i+100),management:true});linked+=Number(result.linked)||0;}await refresh(true);}catch(err){linkError=err.message;}}}$('#dialog').close();render();toast(linkError?'歌曲已匯入；部分共同關聯未完成，請在編輯歌曲補綁：'+linkError:'已匯入，並綁定 '+linked+' 首共同歌曲');}
function backup(data=state,name='backup'){if(demo&&location.origin==='http://127.0.0.1:4173')fetch('/__backup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}).catch(()=>{});const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=`papa-party-${name}-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function migrate(){if(demo)return toast('預覽不讀正式資料');migrationPreview=await api({op:'migrate'});backup(migrationPreview.backup,'v1-before-migration');modal('舊資料移轉核對',`<p>舊資料備份已下載。請先保存。</p><div class="notice">${Object.entries(migrationPreview.counts).map(([k,v])=>`${h(k)}：${v}`).join('<br>')}</div><details><summary>待核對 ${migrationPreview.issues.length} 項</summary><div class="notice warning">${migrationPreview.issues.map(h).join('<br>')}</div></details>${button('保留舊資料，建立 V2','confirmMigration','','primary')}`);}

