let querySequence=0;
const composingInputs=new WeakSet();
document.addEventListener('compositionstart',e=>{composingInputs.add(e.target);if(e.target.id==='login-query')querySequence++;});
document.addEventListener('compositionend',e=>{composingInputs.delete(e.target);updateSearch(e.target);});
document.addEventListener('input',e=>{if(!e.isComposing&&!composingInputs.has(e.target))updateSearch(e.target);});
async function updateSearch(input){const id=input.id;try{
 if(input.matches('[data-entity-query]')){const box=input.closest('.entity-picker');box.querySelector('[type=hidden]').value='';showEntityResults(box);}
 if(id==='login-query'){const seq=++querySequence,q=input.value,rows=demo?playerSearch(full,q,true).slice(0,20):(await api({op:'search',query:q})).players;if(seq!==querySequence||!$('#login-results'))return;$('#login-results').innerHTML=q?rows.map(p=>`<div class="song"><div class="info"><b>${h(p.name)}</b><small>${h(p.ids.join('、'))}</small></div>${button('登入','chooseLogin',p.playerId)}</div>`).join('')||blank('找不到玩家'):'';}
  if(id==='home-search'){const q=input.value;roomSearch.generation++;clearTimeout(roomSearch.timer);$('#home-results').innerHTML=q?blank('搜尋中…'):blank('給我一點線索，幫你翻歌本 ♡');if(q)roomSearch.timer=setTimeout(()=>loadRoomSongSearch('home',q,[],0),350);}
  if(input.matches('[data-tag-search]')){for(const label of document.querySelectorAll('.search-tags label'))label.hidden=!label.textContent.toLocaleLowerCase().includes(input.value.toLocaleLowerCase());}
 if(id==='song-q'){filters.q=input.value;pages[isAdmin()?'songs':'book']=1;roomSearch.generation++;clearTimeout(roomSearch.timer);renderSongResults();if(filters.q.trim())roomSearch.timer=setTimeout(()=>loadRoomSongSearch(isAdmin()?'songs':'book',filters.q,filters.tags,0),350);}
 if(id==='player-query'){const mode=playerManagement.state().mode;playerInputs[mode]=input.value;if(localPlayerManagement()){adminQuery=input.value;pages['players-'+mode]=1;$('#player-results').innerHTML=playerResults(mode);}}
 if(id==='ledger-query'){ledgerQuery=input.value;pages.ledger=1;const holder=document.createElement('div');holder.innerHTML=ledgerRows(null,true);$('#ledger-results').replaceWith(holder.querySelector('#ledger-results'));}
 if(id==='stats-day')$('#stats-result').innerHTML=statsHtml(stats(state,input.value+'T19:00:00+08:00'));
}catch(err){toast(err.message);}}
async function start(){if(demo){const catalog=await (await fetch('src/catalog.json')).json();full=get('demo')||migrateLegacy({songs:catalog,users:[],queue:[],crowns:[]});if(full.schemaVersion<3){put('before-v3',full);seedPreviewCrowns(full);full=upgradePlatform(full);}put('demo',full);}if(route==='admin'&&!admin)route='home';const incoming=new URL(location.href),songId=incoming.searchParams.get('commonRequest'),kind=incoming.searchParams.get('commonKind');if(songId&&songId.length<=200&&['saved','live'].includes(kind)){pendingCommonRequest={songId,kind};incoming.searchParams.delete('commonRequest');incoming.searchParams.delete('commonKind');history.replaceState(null,'',incoming.href);}try{if(entryPending&&!await openSpaceEntry())return;await refresh(true);if(route==='common-book')await loadCommonBook(0);if(pendingCommonRequest){if(session){const item=pendingCommonRequest;pendingCommonRequest=null;await requestSong(item.songId,item.kind);}else await loginDialog();}}catch(e){header();$('#app').innerHTML=card('連線還沒準備好',`<p>${h(e.message)}</p><p class="muted">管理員完成 V2 部署設定後即可使用。現有正式資料沒有被改動。</p>${button('管理入口','admin')}`,true);}}
let lastHour=hourKey(clock());setInterval(()=>{const nextHour=hourKey(clock());if(!entryPending&&!document.hidden&&nextHour!==lastHour&&!busy&&!$('#dialog').open&&!document.activeElement?.matches('input,textarea,select')){lastHour=nextHour;refresh(true).catch(()=>{});}if($('#hour'))$('#hour').innerHTML=hour();},1000);
setInterval(()=>{if(entryPending||document.hidden||$('#dialog').open||document.activeElement?.matches('input,textarea,select')||demo||draft)return;refresh().catch(()=>{});},30000);
setInterval(()=>{if(route==='home'&&$('#photo-carousel')&&!document.hidden){photoIndex++;$('#photo-carousel').innerHTML=photoCarousel();}},8000);
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'home';if(next!==route)go(next).catch(e=>toast(e.message));});

function queueRemovalHint(q){return q.allocation_id?'這首尚未演唱；取消後退回已分配的 '+(q.creditCost||1)+' 首存歌，保留回補與取消紀錄。':q.kind==='saved'?'取消會釋放保留的存歌及提歌額度；完成演唱才扣存歌。':'取消後保留點歌紀錄。';}
async function queueLyrics(id){
 const q=state.queue.find(q=>q.id===id);if(!q)return toast('紀錄已更新');
 const items=q.items?.length?q.items:[{songId:q.songId,title:q.title,artist:q.artist}];
 const part=(item,body,note='')=>'<h3>'+h(item.title||song(item.songId)?.title||q.title)+'</h3><small>'+h(item.artist||song(item.songId)?.artist||'')+'</small><div class="notice catalog-lyric-body">'+h(body||'這首尚未填入歌詞，可到歌曲管理補充。')+'</div>'+(note?'<small>演唱註記：'+h(note)+'</small>':'');
 if(demo||draft){modal('查看歌詞',items.map(item=>part(item,song(item.songId)?.lyrics)).join(''));return;}
 modal('查看歌詞','<div id="queue-lyrics-content">讀取歌詞中…</div>');
 const holder=$('#queue-lyrics-content'),pending=new Map();
 const result=await Promise.all(items.map(async item=>{try{if(!pending.has(item.songId))pending.set(item.songId,api({op:'catalogLyrics',streamerSongId:item.songId,management:true}));const row=await pending.get(item.songId);return part(item,row.body??row.lyrics??song(item.songId)?.lyrics,row.privateNote);}catch(err){return part(item,'歌詞暫時無法載入：'+err.message);}}));
 if(holder&&holder===$('#queue-lyrics-content'))holder.innerHTML=result.join('');
}
function editQueue(id){
 const q=state.queue.find(q=>q.id===id);if(!q||!['waiting','pending'].includes(q.status))return toast('只能編輯尚未演唱的待播');
 const originalPair=q.items?.length>1?q.items[1].songId:'',originalTime=dateInput(q.at),choices=state.songs.map(s=>[s.songId,s.title+'－'+s.artist]);
 if(!choices.some(([id])=>id===q.songId))choices.push([q.songId,q.title+'－'+q.artist]);
 modal('編輯待播／換歌','<p>'+h(playerName(q.playerId))+' · '+(q.kind==='saved'?'提歌':'現點')+'</p>'+select('songId','歌曲',choices,q.songId)+'<div id="queue-edit-options"></div>'+check('selfProvided','自帶／不計熱門與常聽',q.selfProvided)+field('at','實際提出時間',originalTime,'datetime-local','required')+area('note','備註',q.note||'')+'<div id="queue-edit-cost" class="notice" aria-live="polite"></div>',async f=>{
  const data={id,operation:'edit',songId:f.get('songId'),pairSongId:f.get('pairSongId')||'',selfProvided:f.has('selfProvided'),note:f.get('note')};
  if(f.get('at')!==originalTime)data.at=isoInput(f.get('at'));await dispatch('queue',data);toast('待播已更新');
 });
 let shown=null;const update=()=>{
  const current=$('#dialog [name=songId]').value,item=song(current);
  if(current!==shown){shown=current;$('#queue-edit-options').innerHTML=item?shortSongOptions(item):'';
   if(current===q.songId){const originalLabel=originalPair?'保留原搭配：'+(q.items[1].title||'半首歌曲'):'保留原演唱方式';let selectPair=$('#dialog [name=pairSongId]');if(!selectPair&&originalPair){$('#queue-edit-options').innerHTML+=nativeSelect('pairSongId','演唱方式',[[originalPair,originalLabel]],originalPair);selectPair=$('#dialog [name=pairSongId]');}
    if(selectPair){if(![...selectPair.options].some(o=>o.value===originalPair))selectPair.insertAdjacentHTML('beforeend','<option value="'+h(originalPair)+'">'+h(originalLabel)+'</option>');selectPair.value=originalPair;}
   }
  }
  const pair=$('#dialog [name=pairSongId]')?.value||'';try{
   const unchanged=current===q.songId&&pair===originalPair,cost=unchanged?(q.creditCost||1):quoteSong(state,current,{pairSongId:pair},q.playerId,clock()).creditCost,diff=cost-(q.creditCost||1);
   $('#queue-edit-cost').textContent=q.allocation_id?'本首分配 '+cost+' 首；'+(diff>0?'換歌需補用 '+diff+' 首存歌。':diff<0?'換歌退回 '+(-diff)+' 首存歌。':'存歌餘額不變。'):q.kind==='saved'?'完成演唱扣 '+cost+' 首存歌，並占 '+cost+' 首提歌額度。':'現點使用 '+cost+' 首，保留原點歌紀錄。';
  }catch(error){$('#queue-edit-cost').textContent=error.message;}
 };
 $('#modal-form').addEventListener('click',()=>setTimeout(update,0));$('#modal-form').addEventListener('change',update);update();
}

function onBehalf(){modal('新增待播',venueSelector()+select('playerId','玩家',playerOptions(),'')+'<small id="proxy-credits" class="muted" aria-live="polite"></small>'+select('songId','歌曲',state.songs.filter(s=>!s.hidden).map(s=>[s.songId,s.title+'－'+s.artist]),'')+'<div class="proxy-draw-toolbar">'+button('🎲 抽一首','proxyDraw')+'<details id="proxy-fate-category" class="proxy-draw-tags"><summary>完全交給命運／選標籤</summary><div class="chips">'+fateCategories(state.settings,state.songs).map(t=>'<label><input type="checkbox" data-proxy-draw-tag value="'+h('tag:'+t)+'"> '+h(t)+'</label>').join('')+'</div><small class="muted">未選標籤＝完全交給命運；多選符合任一標籤。</small></details></div>'+select('kind','使用方式',[['saved','完成演唱才扣存歌'],['live','現點（待確認禮物）']],'saved')+check('selfProvided','自帶：不列熱門／常聽，照常扣額度')+field('at','實際時間（留空為當下）','','datetime-local')+area('note','備註')+check('completed','補登已完成演唱')+'<p class="muted">補登其他小時的提歌歸入該小時額度；同一小時的補登仍占本小時額度。</p><div id="proxy-cost"></div>',async f=>dispatch('onBehalf',{...formData(f),selfProvided:f.has('selfProvided'),at:isoInput(f.get('at')),completed:f.has('completed'),giftConfirmed:true}));let lastSongId='';const update=()=>{const current=$('#dialog [name=songId]').value,changed=current!==lastSongId;lastSongId=current;const chosen=song(current);if(changed)$('#proxy-cost').innerHTML=chosen?shortSongOptions(chosen)+'<p>提歌完成演唱扣 '+(Number(chosen.creditCost)===0.5?1:chosen.creditCost||1)+' 首存歌，並占用同樣首數的提歌額度；現點不扣存歌、不占提歌額度。</p>':'';updateProxyCredits(chosen);};$('#modal-form').addEventListener('click',()=>setTimeout(update,0));$('#modal-form').addEventListener('change',update);}
function updateProxyCredits(chosen){const holder=$('#proxy-credits'),playerId=$('#dialog [name=playerId]')?.value;if(!holder)return;if(!playerId){holder.textContent='';return;}const venue=$('#dialog [name=venue]')?.value||venuePolicySettings(state.settings).current_space,available=pool=>Math.max(0,balance(state,playerId,pool)-reservedCredits(state,playerId,pool)),reserved=reservedCredits(state,playerId,venue);let text=venue==='radio'?'可用 電台 '+available('radio')+'｜聲瑪 '+available('shengma'):'可用 '+available('shengma');if(reserved)text+='｜保留 '+reserved;const cost=chosen?(Number(chosen.creditCost)===0.5?1:Number(chosen.creditCost||1)):0;if(cost&&$('#dialog [name=kind]')?.value==='saved')text+='｜本次占 '+cost+' 首';holder.textContent=text;}
function installProxyNewButton(){const picker=$('#dialog .entity-picker[data-entity-kind=songId]');if(picker)picker.insertAdjacentHTML('beforebegin','<div class="actions">'+button('＋新增歌曲','proxyNewSong','','tiny')+'</div>');}
function restoreProxyDraft(draft,songId){if(!draft)return;const form=$('#modal-form');for(const key of ['kind','at','note','venue']){const el=form?.querySelector('[name='+key+']');if(el&&(key!=='venue'||['shengma','radio'].includes(draft[key])))el.value=draft[key]||'';}for(const key of ['selfProvided','completed']){const el=form?.querySelector('[name='+key+']');if(el)el.checked=!!draft[key];}for(const [key,id] of [['playerId',draft.playerId],['songId',songId]]){const box=form?.querySelector('.entity-picker[data-entity-kind='+key+']'),row=key==='playerId'?state.players.find(p=>p.playerId===id):song(id);if(box&&row){box.querySelector('[type=hidden]').value=id;box.querySelector('[data-entity-query]').value=key==='playerId'?row.name:row.title+'－'+row.artist;}}form?.querySelector('[name=songId]')?.dispatchEvent(new Event('change',{bubbles:true}));}
async function openProxyNewSong(){const form=$('#modal-form');if(!form)return;const data=new FormData(form);proxyDraft={playerId:data.get('playerId'),kind:data.get('kind'),venue:data.get('venue'),at:data.get('at'),note:data.get('note'),selfProvided:data.has('selfProvided'),completed:data.has('completed'),created:false};await editSong();$('#dialog').addEventListener('close',()=>{if(proxyDraft&&!proxyDraft.created)proxyDraft=null;},{once:true});}

start();

function jumpPage(input){if(!input)return;const n=Number(input.value),max=Number(input.max);if(!Number.isInteger(n)||n<1||n>max){toast('請輸入 1～'+max+' 的頁碼');return;}pages[input.dataset.pageKey]=n;render();}
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-page-key]')){e.preventDefault();jumpPage(e.target);}});
document.addEventListener('change',e=>{if(e.target.id==='song-language'){filters.language=e.target.value;pages={};roomSearch.generation++;clearTimeout(roomSearch.timer);renderSongResults();if(filters.q.trim())loadRoomSongSearch(isAdmin()?'songs':'book',filters.q,filters.tags,0);}if(e.target.matches('[data-filter-tag]')){filters.tags=Array.from(document.querySelectorAll('[data-filter-tag]:checked'),x=>x.dataset.filterTag);pages={};roomSearch.generation++;render();if((route==='book'||isAdmin()&&tab==='songs')&&filters.q.trim())loadRoomSongSearch(isAdmin()?'songs':'book',filters.q,filters.tags,0);}});

function select(name,label,values,value){if(!['playerId','songId'].includes(name))return nativeSelect(name,label,values,value);const match=values.find(v=>String(v[0])===String(value)),optional=label.includes('選填');return `<div class="entity-picker" data-entity-kind="${name}"><label>${h(label)}<input type="search" data-entity-query autocomplete="off" placeholder="${name==='playerId'?'搜尋玩家名稱、ID、曾用名':'搜尋歌名、歌手、語言、標籤'}" value="${h(match?.[0]?match[1]:'')}" aria-label="${h(label)}搜尋" ${optional?'':'required'}></label><input type="hidden" name="${name}" value="${h(value||'')}"><div class="entity-results"></div></div>`;}
function showEntityResults(box){const input=box.querySelector('[data-entity-query]'),q=input.value.trim(),kind=box.dataset.entityKind,rows=q?(kind==='playerId'?playerSearch(state,q):state.songs.filter(s=>matchesSong(s,q))):[];box.querySelector('.entity-results').innerHTML=q?(rows.slice(0,12).map(r=>button(h(kind==='playerId'?r.name+' · '+(r.ids.join('、')||'無平台 ID'):r.title+'－'+r.artist),'pickEntity',kind==='playerId'?r.playerId:r.songId,'entity-option')).join('')||'<small>沒有符合的資料</small>')+(rows.length>12?'<small>再輸入幾個字，縮小搜尋範圍 ♡</small>':''):'';}

document.addEventListener('submit',e=>{for(const box of e.target.querySelectorAll('.entity-picker')){const input=box.querySelector('[data-entity-query]');if((input.required||input.value.trim())&&!box.querySelector('[type=hidden]').value){e.preventDefault();e.stopImmediatePropagation();$('#dialog-error').textContent='請從搜尋結果點選正確的玩家或歌曲';input.focus();return;}}},true);
function seedPreviewCrowns(s){if(s.previewCrownsRestored)return;s.previewCrownsRestored=true;for(const [id,title,artist] of [['legacy-crown-1','三心愛意','不不玩家'],['legacy-crown-2','crazy 1 night','葵葵']]){if(!s.crowns.some(c=>c.id===id||c.title===title))s.crowns.push({id,title,artist,ownerName:'不不玩家',playerId:null,songId:null,tier:'至尊卡',fee:925000,price:55599,double:18188,months:0,activatedAt:null,expiresAt:null,legacyDisplay:true,note:'原網站冠歌：永久；生效時間未知。請核對綁定與款項，不自動設定生效時間。'});}}

function playerResults(mode='stored'){let rows=playerSearch(state,adminQuery);if(mode==='stored')rows=rows.filter(p=>balance(state,p.playerId)>0);const page=paginate(rows,'players-'+mode);return playerRowsHtml(page.rows)+page.nav;}

function adminSongPage(){return bookSearchResult()||paginate(filteredSongs(),'songs',20);}
function adminSongList(){const p=adminSongPage();return p.loading?blank('搜尋中…'):adminSongResults(p.rows)+(p.nav||'');}
function adminSongResults(rows=adminSongPage().rows){return rows.map(s=>{const status=s.catalogStatus||'unlinked';return `<div class="song selectable-song ${selectedSongs.has(s.songId)?'is-selected':''}"><label class="song-check"><input type="checkbox" data-song-select="${h(s.songId)}" aria-label="選取 ${h(s.title)}" ${selectedSongs.has(s.songId)?'checked':''}></label><div class="info"><b>${h(s.title)}${s.new?' <span class="tag">✨ 新練</span>':''}${s.hidden?' <span class="tag">已隱藏</span>':''}</b><small>${h(s.artist)} · ${h(s.cat)} · ${plays(s)} 次</small><small>${h(({linked:'已綁定',pending:'待審核',unlinked:'未綁定'})[status])}${status==='linked'?' · '+h(s.version||'原版'):''}</small><div class="song-tags">${s.tags?.length?s.tags.map(t=>`<span class="tag">${h(t)}</span>`).join(''):'<small class="subtle">尚未貼標籤</small>'}</div>${s.murmur?`<div class="subtle">💬 ${h(s.murmur)}</div>`:''}</div><div class="actions song-primary-actions">${s.hidden?button('恢復顯示','songHide',s.songId,'tiny'):''}${button('編輯','editSong',s.songId)}${button('刪除','deleteSong',s.songId,'tiny danger')}<details class="song-more"><summary>更多</summary><div class="actions">${status==='linked'?(Number(s.otherStreamerCount)>0?button('誰也會唱','songOtherSingers',s.songId):''):button('前往共同曲庫','songLink',s.songId)}${button(s.hidden?'解除隱藏':'隱藏','songHide',s.songId)}${button('💬 碎碎念','editMurmur',s.songId)}${button('歌詞／註記','streamerLyrics',s.songId)}</div></details></div></div>`;}).join('')||blank('沒有符合的歌曲');}
function songBatchBar(){for(const id of selectedSongs)if(!song(id))selectedSongs.delete(id);const found=bookSearchResult(),matches=found?found.rows:filteredSongs(),visible=found?found.rows:adminSongPage().rows,all=visible.length&&visible.every(s=>selectedSongs.has(s.songId));return `<div class="batch-toolbar"><label class="check-row"><input type="checkbox" data-select-song-page ${all?'checked':''} ${visible.length?'':'disabled'}>本頁全選</label><strong role="status" aria-live="polite">已選 ${selectedSongs.size} 首</strong>${button((found?'選取本頁搜尋結果（':'選取搜尋結果（')+matches.length+'）','selectFilteredSongs','', 'tiny', matches.length?'':'disabled')}${button('取消選取','clearSongSelection','','tiny',selectedSongs.size?'':'disabled')}${button('批次編輯／貼標籤','bulkEditSongs','','tiny primary',selectedSongs.size?'':'disabled')}${button('刪除已選','deleteSelectedSongs','','tiny danger',selectedSongs.size?'':'disabled')}${songUndo&&songUndo.until>Date.now()?button('復原剛才的批次修改','undoSongBatch'):''}</div><small>可跨頁選取；搜尋不會清除已選歌曲。</small>`;}
function renderSongResults(){if(!$('#song-list'))return;const p=isAdmin()?adminSongPage():bookSearchResult()||paginate(filteredSongs(),'book',20);$('#song-list').innerHTML=p.loading?blank('搜尋中…'):(isAdmin()?adminSongResults(p.rows):songRows(p.rows))+(p.nav||'');if($('#song-batch-bar')){$('#song-batch-bar').innerHTML=songBatchBar();const rows=p.rows,checked=rows.filter(s=>selectedSongs.has(s.songId)).length,all=$('[data-select-song-page]');if(all)all.indeterminate=checked>0&&checked<rows.length;}}
document.addEventListener('change',e=>{if(e.target.id==='song-catalog-status'){songCatalogStatusFilter=e.target.value;pages.songs=1;roomSearch.generation++;clearTimeout(roomSearch.timer);renderSongResults();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-song-select]')){const id=e.target.dataset.songSelect;e.target.checked?selectedSongs.add(id):selectedSongs.delete(id);renderSongResults();}if(e.target.matches('[data-select-song-page]')){for(const s of adminSongPage().rows)e.target.checked?selectedSongs.add(s.songId):selectedSongs.delete(s.songId);renderSongResults();}});
const songEditFields=s=>({cat:s.cat,artistType:s.artistType,tags:s.tags||[],new:!!s.new,murmur:s.murmur||'',creditCost:s.creditCost??1});
async function deleteSelectedSongs(){
 const ids=[...selectedSongs].filter(id=>song(id));if(!ids.length)return;
 if(!confirm('刪除已選 '+ids.length+' 首歌曲？既有演唱與點歌歷史保留。有待播、有效冠歌或半首搭配依賴時，整批不會刪除。'))return;
 await dispatch('songsBulk',{songIds:ids,remove:true});selectedSongs.clear();songUndo=null;renderSongResults();toast('已刪除 '+ids.length+' 首歌曲');
}
async function bulkEditSongs(){const ids=[...selectedSongs].filter(id=>song(id));if(!ids.length)return toast('先勾選要修改的歌曲');const languages=await catalogTemplateChoices('languages','',['華語','韓語','台語','其他']),types=await catalogTemplateChoices('performerTypes','',['女歌手','男歌手','團體','合唱','其他']);modal('批次編輯 '+ids.length+' 首歌曲',`<details class="notice"><summary>查看這次選取的 ${ids.length} 首</summary><div class="batch-selection">${ids.map(id=>h(song(id).title)+'－'+h(song(id).artist)).join('<br>')}</div></details><p class="muted">只改你指定的欄位，其餘資料保留。</p><div class="form-grid">${nativeSelect('tagMode','標籤處理',[['keep','不變'],['add','加上勾選標籤'],['remove','移除勾選標籤'],['replace','改成以下標籤'],['clear','清空標籤']],'keep')}${nativeSelect('cat','語言',[['','不變'],...languages],'')}<div class="full chips batch-tag-options">${state.settings.tags.map(t=>check('tags',t).replace('name="tags"',`name="tags" value="${h(t)}"`)).join('')}</div>${field('customTags','其他標籤（逗號分開）')}${nativeSelect('artistType','歌手分類',[['','不變'],...types],'')}${nativeSelect('new','新練歌曲',[['','不變'],['true','設為新練'],['false','取消新練']],'')}${nativeSelect('murmurMode','碎碎念',[['keep','不變'],['set','統一填寫'],['clear','清空']],'keep')}${field('creditCost','統一扣歌首數（空白不變）','','number','min="0.5" step="0.5"')}${field('murmur','統一的碎碎念','','text','maxlength="40"')}</div><div id="batch-preview" class="notice" aria-live="polite">尚未指定修改項目</div>`,async f=>{const data=bulkSongData(f,ids),before=ids.map(id=>({songId:id,...songEditFields(song(id))}));await dispatch('songsBulk',data);songUndo={before,after:ids.map(id=>({songId:id,...songEditFields(song(id))})),until:Date.now()+10000};clearTimeout(songUndoTimer);songUndoTimer=setTimeout(()=>{songUndo=null;if($('#song-batch-bar'))$('#song-batch-bar').innerHTML=songBatchBar();},10000);renderSongResults();toast('已更新 '+ids.length+' 首歌曲，可在 10 秒內復原');});const form=$('#modal-form');form.addEventListener('change',()=>updateBulkPreview(form,ids));form.addEventListener('input',e=>{if(!e.isComposing)updateBulkPreview(form,ids);});}
function bulkSongData(f,ids){const data={songIds:ids,tagMode:f.get('tagMode'),tags:[...f.getAll('tags'),...list(f.get('customTags'))]};for(const k of ['cat','artistType'])if(f.get(k))data[k]=f.get(k);if(f.get('creditCost'))data.creditCost=Number(f.get('creditCost'));if(f.get('new'))data.new=f.get('new')==='true';if(f.get('murmurMode')!=='keep')data.murmur=f.get('murmurMode')==='clear'?'':f.get('murmur');return data;}
function updateBulkPreview(form,ids){const f=new FormData(form);if((f.getAll('tags').length||f.get('customTags').trim())&&f.get('tagMode')==='keep'){form.elements.tagMode.value='add';f.set('tagMode','add');}const d=bulkSongData(f,ids),parts=[];if(d.tagMode!=='keep')parts.push(({add:'加上標籤：',remove:'移除標籤：',replace:'改成標籤：',clear:'清空標籤'})[d.tagMode]+(d.tagMode==='clear'?'':d.tags.join('、')));if(d.creditCost)parts.push('扣歌首數：'+d.creditCost);if(d.cat)parts.push('語言：'+d.cat);if(d.artistType)parts.push('歌手分類：'+d.artistType);if('new'in d)parts.push(d.new?'設為新練歌曲':'取消新練');if('murmur'in d)parts.push(d.murmur?'碎碎念：'+d.murmur:'清空碎碎念');$('#batch-preview').textContent=parts.length?'將修改 '+ids.length+' 首：'+parts.join('；'):'尚未指定修改項目';}
async function undoSongBatch(){if(!songUndo||songUndo.until<Date.now())return toast('復原時間已過');const undo=songUndo;await dispatch('restoreSongEdits',{before:undo.before,after:undo.after});songUndo=null;clearTimeout(songUndoTimer);renderSongResults();toast('已復原剛才的批次修改');}

function editStreamer(id){const r=state.streamers.find(r=>r.id===id)||{};modal(id?'編輯主播':'新增主播',field('display_name','主播名稱',r.display_name||'','text','required')+field('slug','網址名稱（英文）',r.slug||'','text','required')+field('home_title','首頁名稱',r.home_title||'')+field('subtitle','副標題',r.subtitle||'')+field('avatar_url','頭像網址',r.avatar_url||'')+field('banner_url','橫幅網址',r.banner_url||'')+area('description','介紹',r.description||'')+check('active','開放主播頁',r.active!==false),async f=>dispatch('streamer',{...formData(f),id:r.id,active:f.has('active')}));}
