function eventHtml(x){return '<article class="notice"><b>'+h(eventDescription(x,{playerName,songName:id=>song(id)?.title,roomName:id=>state.streamers.find(r=>r.id===id)?.display_name||'管理端'}))+'</b><small> · '+h(time(x.created_at||x.createdAt))+'</small><details><summary>技術詳情</summary><pre class="event-detail">'+h(JSON.stringify(x,null,2))+'</pre></details></article>';}
async function loadEvents(){const holder=$('#event-list');if(!holder)return;try{if(demo||draft){holder.innerHTML=blank('永久操作歷史於正式同步時由伺服器記錄。');return;}const page=eventPage,r=await api({op:'events',page});if(holder!==$('#event-list')||page!==eventPage)return;if(!Array.isArray(r.rows))throw Error('操作歷史回傳格式不正確，請重新讀取');holder.innerHTML=r.rows.map(eventHtml).join('')||blank('尚無新操作紀錄');holder.innerHTML+='<div class="actions">'+button('上一頁','eventPage','-1','tiny',eventPage?'':'disabled')+'<small>第 '+(eventPage+1)+' 頁</small>'+button('下一頁','eventPage','1','tiny',r.hasMore?'':'disabled')+'</div>';}catch(e){holder.textContent=e.message;}}
function allocateDialog(id,initial={}){const old=state.ledger.find(l=>l.id===id);modal('收到歌單：分配現點／存歌',venueSelector('venue',old?venuePolicyLedgerPool(old):initial.storage_pool||venuePolicySettings(state.settings).current_space)+select('playerId','玩家',playerOptions(old?.playerId),old?.playerId||initial.playerId||'')+field('total','收到總首數',old?.amount||Number(initial.amount)||3,'number','min="0.5" step="0.5" required '+(old?'readonly':''))+field('stored','保留存歌首數',old?.amount||Number(initial.amount)||2,'number','min="0" step="0.5" required')+field('effective_at','實際收到時間',dateInput(old?.at||initial.at||clock()),'datetime-local','required')+area('note','備註',old?.note||initial.note||'')+check('openingBalance','歷史／初始存歌（不計當日收到）',old?.openingBalance||old?.note==='初始存歌')+'<p class="muted">存歌首數＋下方現點用額必須等於總首數。已收到禮物的現點直接排入待唱；選擇已唱則補登完成。</p><div id="allocation-rows"></div>'+button('＋加入現點歌曲','allocationRow'),async(f,form)=>{const items=[...form.querySelectorAll('.allocation-row')].map(row=>({songId:row.querySelector('[name=songId]').value,pairSongId:row.querySelector('[name=pairSongId]')?.value||'',completed:row.querySelector('[name=completed]').checked,selfProvided:row.querySelector('[name=selfProvided]').checked}));await dispatch('allocate',{...formData(f),ledgerId:old?.id,items,effective_at:isoInput(f.get('effective_at')),openingBalance:f.has('openingBalance')});});}
function addAllocationRow(){const div=document.createElement('div');div.className='allocation-row notice';div.innerHTML=select('songId','現點歌曲',state.songs.map(s=>[s.songId,s.title+'－'+s.artist]),'')+'<div class="allocation-cost"></div>'+check('selfProvided','自帶／不計熱門與常聽')+check('completed','此首已完成演唱')+button('移除此列','removeAllocationRow');$('#allocation-rows').append(div);let previous='';div.addEventListener('click',()=>setTimeout(()=>{const id=div.querySelector('[name=songId]').value;if(id===previous)return;previous=id;const s=song(id);div.querySelector('.allocation-cost').innerHTML=s?shortSongOptions(s)+'<p>使用 '+(Number(s.creditCost)===0.5?1:s.creditCost||1)+' 首額度</p>':'';},0));}

