function openCatalogIssueForm(row){if(!isAdmin()||!row?.familyId)return;modal('回報共同曲庫問題','<p>《'+h(row.title)+'》 · '+h(row.artist)+'</p>'+nativeSelect('issueType','問題類型',[['song_info','歌曲資訊錯誤'],['artist_name','歌手名稱錯誤'],['performer_type','歌手分類錯誤'],['language','語言錯誤'],['version_type','原唱／翻唱版本錯誤'],['missing_version','缺少其他版本'],['version_relation','版本關係錯誤'],['duplicate','疑似重複'],['other','其他']],'other')+area('description','補充說明','')+area('suggestion','建議修改',''),async f=>{await api({op:'catalogIssueReport',familyId:row.familyId,variantId:row.variantId||null,issueType:f.get('issueType'),description:f.get('description'),suggestion:f.get('suggestion'),management:true});toast('已送出問題回報');});}
