async function selectedGroupDecision(groupId,decision){
 const group=groupId?catalogView.groups.find(g=>g.id===groupId):null;
 const rows=[...catalogView.selected].map(id=>catalogView.selectedRows.get(id)).filter(r=>r&&(!group||r.groupId===group.id));
 if(!rows.length||(['confirm_same','different_versions'].includes(decision)&&rows.length<2))return toast(decision==='independent'?'請勾選至少 1 筆':'請勾選至少 2 筆');
 if(rows.length>50)return toast('一次請選最多 50 筆');
 if(decision==='different_versions'){
  const versionFields=rows.map((r,i)=>'<fieldset class="catalog-version-form"><legend>'+h((state.streamers.find(s=>s.id===r.streamerId)?.display_name||r.streamerId)+' · '+r.title+'｜'+r.artist)+'</legend>'+field('artist'+i,'演唱者',r.artist,'text','maxlength="300"')+field('version'+i,'版本名稱',r.versionLabel||'版本 '+(i+1),'text','required maxlength="120"')+field('language'+i,'語言',r.language||'','text','maxlength="100"')+field('performer'+i,'歌手類型',r.performerType||'','text','maxlength="100"')+field('kind'+i,'版本類型',r.versionKind||'original','text','maxlength="80"')+field('detail'+i,'演唱者補充',r.performerDetail||'','text','maxlength="300"')+field('note'+i,'版本備註',r.versionNote||'','text','maxlength="500"')+'</fieldset>').join('');
  modal('同一作品的不同版本','<p>共同作品只建立一次；以下每個來源會各自成為一個版本。</p>'+field('commonTitle','共同歌名',rows[0].title,'text','required maxlength="300"')+versionFields,async f=>{
   const commonTitle=f.get('commonTitle')?.trim();if(!commonTitle)throw Error('請輸入共同歌名');
   const variantMetadata=Object.fromEntries(rows.map((r,i)=>[r.id,{artist:f.get('artist'+i)||'',versionLabel:f.get('version'+i)||'',language:f.get('language'+i)||'',performerType:f.get('performer'+i)||'',versionKind:f.get('kind'+i)||'',performerDetail:f.get('detail'+i)||'',versionNote:f.get('note'+i)||''}]));
   if(Object.values(variantMetadata).some(v=>!v.versionLabel.trim()))throw Error('每個版本都需要名稱');
   const confirmation='確認建立《'+commonTitle+'》的 '+rows.length+' 個版本？\n'+rows.map(r=>variantMetadata[r.id].versionLabel+'｜'+variantMetadata[r.id].artist).join('\n')+'\n所有主播原歌曲與歷史保留。';
   await catalogReviewAction(decision,rows.map(r=>r.id),{commonMetadata:{title:commonTitle},variantMetadata,confirmation,...(rows.every(r=>r.preferredFamily&&r.preferredFamily===rows[0].preferredFamily)?{familyId:rows[0].preferredFamily}:{})});
  });return;
 }if(decision!=='confirm_same')return catalogReviewAction(decision,rows.map(r=>r.id));
 const sourceNames=rows.map(r=>r.title+'｜'+r.artist+'（'+(state.streamers.find(s=>s.id===r.streamerId)?.display_name||r.streamerId)+'）');
 const mergeField=(key,label,max)=>field(key,label,rows[0][key]||'','text',(key==='title'?'required ':'')+'maxlength="'+max+'" list="merge-'+key+'"')+'<datalist id="merge-'+key+'">'+[...new Set(rows.map(r=>r[key]||''))].filter(Boolean).map(v=>'<option value="'+h(v)+'">').join('')+'</datalist>';
 modal('合併已勾選的 '+rows.length+' 筆','<p>只處理以下來源；未勾選的歌曲留在原群組。欄位可選來源候選，也可輸入正確內容。</p><div class="notice">'+sourceNames.map(h).join('<br>')+'</div>'+mergeField('title','共同歌名',300)+mergeField('artist','共同歌手',300)+mergeField('language','語言',100)+mergeField('performerType','演唱類型',100)+mergeField('versionLabel','版本名稱',120)+field('versionKind','版本類型（原版／翻唱等）','original','text','maxlength="80"')+mergeField('performerDetail','演唱者補充',300)+mergeField('versionNote','版本備註',500)+'<h3>歌詞處理</h3><p>只使用本次勾選的來源；所有主播 custom 歌詞保留。</p>'+rows.map(r=>'<small>'+h((state.streamers.find(s=>s.id===r.streamerId)?.display_name||r.streamerId)+'：'+(r.hasCustomLyrics?'自訂歌詞 ✓':'無自訂歌詞'))+'</small>').join('<br>')+nativeSelect('lyricsSource','建立共同歌詞',[['','本次先略過'],...rows.filter(r=>r.hasCustomLyrics).map(r=>[r.id,'採用 '+(state.streamers.find(s=>s.id===r.streamerId)?.display_name||r.streamerId)+' 的歌詞']),['manual','手動建立／編輯']],'')+area('sharedBody','手動共同歌詞（選手動建立時才使用）','')+button('查看所選來源歌詞','catalogPreviewSelectedLyric'),async f=>{
  const source=f.get('lyricsSource'),title=f.get('title')?.trim();if(!title)throw Error('請輸入共同歌名');
  const preview='確認將 '+rows.length+' 筆合併為《'+title+'》｜'+f.get('artist')+'？\n版本：'+(f.get('versionLabel')||'原版')+' · '+f.get('versionKind')+'\n語言／類型：'+f.get('language')+' · '+f.get('performerType')+'\n補充／備註：'+f.get('performerDetail')+' · '+f.get('versionNote')+'\n來源：'+sourceNames.join('、')+'\n歌詞：'+(source==='manual'?'手動建立':source?'採用選取的主播歌詞':'暫不建立')+'\n主播私有資料和歌詞保留。';
  await catalogReviewAction('confirm_same',rows.map(r=>r.id),{commonMetadata:Object.fromEntries(['title','artist','language','performerType','versionLabel'].map(k=>[k,f.get(k)||''])),variantDetails:Object.fromEntries(['versionKind','performerDetail','versionNote'].map(k=>[k,f.get(k)||''])),confirmation:preview,...(source==='manual'?{sharedBody:f.get('sharedBody')}:source?{lyricsSource:source}:{})});
 });
 $('#dialog [data-act=catalogPreviewSelectedLyric]').onclick=async()=>{const id=$('#dialog [name=lyricsSource]').value,r=rows.find(x=>x.id===id);if(!r)return toast('先選擇一位主播歌詞來源');const data=await api({op:'catalogLyrics',streamer:r.streamerId,streamerSongId:r.songId,management:true});$('#dialog [name=sharedBody]').value=data.body||'';};
}
function installSongAutocomplete(){
 const form=$('#modal-form'),input=form.querySelector('[name=title]'),box=$('#song-catalog-candidates');let timer,generation=0;
 form.querySelector('[type=submit]').textContent='新增為全新歌曲';
 const label=input.closest('label'),row=document.createElement('div');row.className='full song-title-row';label.replaceWith(row);row.append(label);row.insertAdjacentHTML('beforeend','<div class="song-title-actions">'+button('從共同曲庫選歌（批量）','catalogBrowse','','tiny')+'<small>輸入至少 2 個字，搜尋共同曲庫。</small></div>');
 const cleanup=()=>{clearTimeout(timer);generation++;};$('#dialog').addEventListener('close',cleanup,{once:true});
 input.addEventListener('input',()=>{clearTimeout(timer);const g=++generation,q=input.value.trim();form.querySelector('[name=catalogCandidateFamily]').value='';form.querySelector('[type=submit]').textContent='新增為全新歌曲';if(q.length<2){box.innerHTML='';return;}
  timer=setTimeout(async()=>{try{const result=await api({op:'catalogSearch',q,limit:8,offset:0,management:true});if(g!==generation||!form.isConnected)return;
   box.innerHTML=(result.items||[]).map(r=>'<div class="song"><div class="info"><b>'+h(r.title)+'</b><small>'+h([r.artist,r.language,r.performerType,r.versionLabel||'原版'].filter(Boolean).join(' · '))+'</small></div><div class="actions"><button type="button" data-add-variant="'+h(r.variantId)+'" '+(r.alreadyAdded?'disabled':'')+'>'+(r.alreadyAdded?'已在我的歌本':'加入我的歌本')+'</button><button type="button" data-new-version="'+h(r.variantId)+'">這是同一首，但我的版本不同</button></div></div>').join('')||'<small>沒有符合的共同歌曲，可新增為全新歌曲。</small>';
   box.onclick=async e=>{const b=e.target.closest('[data-add-variant],[data-new-version]');if(!b)return;const row=result.items.find(r=>r.variantId===(b.dataset.addVariant||b.dataset.newVersion));if(!row)return;
    if(b.dataset.addVariant){b.disabled=true;try{await api({op:'catalogBatchAdd',variantIds:[row.variantId],lyricsMode:'shared',management:true});const draft=proxyDraft;if(draft)draft.created=true;invalidateCatalogTabs();$('#dialog').close();await refresh(true);if(draft){proxyDraft=null;onBehalf();installProxyNewButton();restoreProxyDraft(draft,state.songs.find(s=>s.catalogVariantId===row.variantId)?.songId);}toast('已加入我的歌本');}catch(err){b.disabled=false;toast(err.message);}return;}
    for(const [key,value] of Object.entries({title:row.title,artist:row.artist,cat:row.language,artistType:row.performerType,catalogCandidateFamily:row.familyId})){const x=form.querySelector('[name='+key+']');if(x)x.value=value;}
    form.querySelector('[name=version]').focus();form.querySelector('[type=submit]').textContent='送審：同一首、不同版本';box.innerHTML='<p>已指定《'+h(row.title)+'》作品，請填入你的版本；尚未建立正式共同版本。</p>';
   };
  }catch(err){if(g===generation&&form.isConnected)box.innerHTML='<small class="error">'+h(err.message)+'</small>';}
  },400);
 });
}
async function showLyricProposals(variantId,offset=0){
 const response=await api({op:'catalogLyricSources',variantId,limit:3,offset,management:true});
 modal('可採用的主播歌詞（'+response.total+'）','<div id="catalog-proposals">'+((response.rows||[]).map((r,i)=>'<section class="notice"><b>'+h(state.streamers.find(s=>s.id===r.streamerId)?.display_name||r.streamerId)+'</b><small>'+h(time(r.updatedAt))+'</small><div class="actions"><button type="button" data-proposal-view="'+i+'">查看／比較歌詞</button><button type="button" data-proposal-adopt="'+i+'">採用為共同歌詞</button><button type="button" data-proposal-skip="'+i+'">略過</button></div><pre id="proposal-body-'+i+'"></pre></section>').join('')||blank('沒有待處理歌詞'))+'</div>');
 if(offset+3<response.total){const next=document.createElement('button');next.type='button';next.textContent='下一批來源';next.onclick=()=>showLyricProposals(variantId,offset+3);$('#catalog-proposals').append(next);}
 $('#catalog-proposals').addEventListener('click',async e=>{const b=e.target.closest('[data-proposal-view],[data-proposal-adopt],[data-proposal-skip]');if(!b)return;const i=Number(b.dataset.proposalView??b.dataset.proposalAdopt??b.dataset.proposalSkip),r=response.rows[i];try{
  if(b.dataset.proposalView!=null){const data=await api({op:'catalogLyrics',streamer:r.streamerId,streamerSongId:r.songId,management:true});$('#proposal-body-'+i).textContent=data.body||'';return;}
  if(b.dataset.proposalAdopt!=null&&!confirm('複製這份歌詞建立共同歌詞？來源主播自訂歌詞保留。'))return;
  await api({op:'catalogLyricAdopt',variantId,sourceStreamer:r.streamerId,streamerSongId:r.songId,expectedUpdated:r.updatedAt,skip:b.dataset.proposalSkip!=null,management:true});invalidateCatalogTabs();await showLyricProposals(variantId);
 }catch(err){toast(err.message);}});
}

