function recordTime(table,id){
 if(!isAdmin())throw Error('請先登入管理');
 const row=state[table]?.find(x=>x.id===id);if(!row)throw Error('紀錄已異動');
 const history=table==='queue'&&!['pending','waiting'].includes(row.status);
 const fields=history?['effective_at']:({queue:['at'],ledger:['at'],crowns:['activatedAt','expiresAt'],cards:['startsAt','expiresAt'],wishes:['at']}[table]||[]).filter(key=>row[key]||key==='at');
 if(!fields.length)throw Error('此紀錄尚無可修改的時間');
 const value=key=>key==='effective_at'?row.effective_at||row.completedAt||row.cancelledAt||row.storedAt||row.at:row[key];
 const original=row.original_times&&(row.original_times.effective_at||row.original_times.completedAt||row.original_times.at);
 modal(history?'修改歷史時間':'時間／備註',fields.map(key=>field(key,history?'歷史實際時間':({at:'實際時間',activatedAt:'生效時間',expiresAt:'到期時間',startsAt:'開始時間'}[key]),dateInput(value(key)),'datetime-local','required')).join('')+area('note','備註',row.note||'')+(original?'<p class="muted">原始時間：'+time(original)+'</p>':'')+(history&&row.kind==='saved'?'<p class="muted">修改後會同步重新計算該小時的共用與專屬提歌額度。存歌扣款首數不變。</p>':''),async f=>dispatch('recordTime',{table,id,times:Object.fromEntries(fields.map(key=>[key,isoInput(f.get(key))])),note:f.get('note')}));
}
